Contents of file weather-app/app.js:

1 | /**
2 |  * app.js – Weather Dashboard (SDLC Harness Demo)
3 |  *
4 |  * This file owns all runtime behaviour:
5 |  *  - Mock weather data generation (deterministic, city-name based)
6 |  *  - Search form submission and validation
7 |  *  - Loading state management
8 |  *  - Weather card rendering
9 |  *  - Light/dark theme toggle with localStorage persistence
10 |  */
11 | 
12 | /* ------------------------------------------------------------------ */
13 | /* 1. Mock data                                                        */
14 | /*                                                                     */
15 | /* There is no external API.  Instead we derive pseudo-random but      */
16 | /* stable values from the city name using a simple hash function so    */
17 | /* that the same city always returns the same numbers, which makes     */
18 | /* demo walkthroughs repeatable.                                       */
19 | /* ------------------------------------------------------------------ */
20 | 
21 | /**
22 |  * A small set of weather conditions to choose from.
23 |  * @type {string[]}
24 |  */
25 | const WEATHER_CONDITIONS = [
26 |   'Sunny', 'Partly Cloudy', 'Overcast', 'Light Rain',
27 |   'Thunderstorm', 'Snow Flurries', 'Foggy', 'Windy', 'Clear',
28 | ];
29 | 
30 | /**
31 |  * Compute a simple, non-cryptographic hash of a string.
32 |  * Returns a non-negative integer.  Used to seed mock data from the
33 |  * city name so results are deterministic.
34 |  *
35 |  * @param {string} str
36 |  * @returns {number}
37 |  */
38 | function hashString(str) {
39 |   let hash = 0;
40 |   for (let i = 0; i < str.length; i++) {
41 |     hash = (hash * 31 + str.charCodeAt(i)) >>> 0; // keep unsigned 32-bit
42 |   }
43 |   return hash;
44 | }
45 | 
46 | /**
47 |  * Generate deterministic mock weather data for the given city.
48 |  *
49 |  * @param {string} city  City name as entered by the user.
50 |  * @returns {{city: string, tempF: number, condition: string, humidity: string, wind: string, updatedAt: string}}
51 |  */
52 | function getMockWeather(city) {
53 |   const seed = hashString(city.toLowerCase().trim());
54 | 
55 |   // Temperature: 20 °F – 100 °F range
56 |   const tempF = 20 + (seed % 81);
57 | 
58 |   // Pick a condition from the list
59 |   const condition = WEATHER_CONDITIONS[seed % WEATHER_CONDITIONS.length];
60 | 
61 |   // Humidity: 20 % – 95 %
62 |   // NOTE: >>> not >>. The seed is an unsigned 32-bit value, but `>>` coerces
63 |   // to signed first, so any seed >= 2^31 went negative and produced
64 |   // impossible readings (e.g. London: -3 % humidity, -22 mph wind).
65 |   const humidity = (20 + ((seed >>> 4) % 76)) + '%';
66 | 
67 |   // Wind speed: 0 – 40 mph
68 |   const wind = ((seed >>> 8) % 41) + ' mph';
69 | 
70 |   // Current timestamp
71 |   const now = new Date();
72 |   const updatedAt = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
73 | 
74 |   return {
75 |     city: toTitleCase(city.trim()),
76 |     tempF,
77 |     condition,
78 |     humidity,
79 |     wind,
80 |     updatedAt,
81 |   };
82 | }
83 | 
84 | /**
85 |  * Convert a string to title case (first letter of each word capitalised).
86 |  *
87 |  * @param {string} str
88 |  * @returns {string}
89 |  */
90 | function toTitleCase(str) {
91 |   return str.replace(/\w\S*/g, (word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase());
92 | }
93 | 
94 | /* ------------------------------------------------------------------ */
95 | /* 2. DOM references                                                   */
96 | /* ------------------------------------------------------------------ */
97 | const searchForm        = document.getElementById('search-form');
98 | const cityInput         = document.getElementById('city-input');
99 | const searchBtn         = document.getElementById('search-btn');
100 | const validationMsg     = document.getElementById('validation-message');
101 | const loadingOverlay    = document.getElementById('loading-overlay');
102 | const cardCity          = document.getElementById('card-city');
103 | const cardTemp          = document.getElementById('card-temp');
104 | const cardCondition     = document.getElementById('card-condition');
105 | const cardHumidity      = document.getElementById('card-humidity');
106 | const cardWind          = document.getElementById('card-wind');
107 | const cardUpdated       = document.getElementById('card-updated');
108 | const themeToggleBtn    = document.getElementById('theme-toggle');
109 | 
110 | /* ------------------------------------------------------------------ */
111 | /* 3. UI state helpers                                                  */
112 | /* ------------------------------------------------------------------ */
113 | 
114 | /**
115 |  * Update the weather card with new data.
116 |  *
117 |  * @param {{city: string, tempF: number, condition: string, humidity: string, wind: string, updatedAt: string}} data
118 |  */
119 | function renderWeatherCard(data) {
120 |   cardCity.textContent      = data.city;
121 |   cardTemp.textContent      = data.tempF;
122 |   cardCondition.textContent = data.condition;
123 |   cardHumidity.textContent  = data.humidity;
124 |   cardWind.textContent      = data.wind;
125 |   cardUpdated.textContent   = 'Last updated: ' + data.updatedAt;
126 | }
127 | 
128 | /**
129 |  * Show or hide the loading overlay that sits above the weather card.
130 |  * The search button is disabled while loading to prevent duplicate requests.
131 |  *
132 |  * @param {boolean} isLoading
133 |  */
134 | function setLoading(isLoading) {
135 |   loadingOverlay.hidden = !isLoading;
136 |   searchBtn.disabled    = isLoading;
137 | }
138 | 
139 | /**
140 |  * Show a validation error on the input.
141 |  * Clears automatically on the next successful search.
142 |  *
143 |  * @param {string} message  Human-readable error text.
144 |  */
145 | function showValidationError(message) {
146 |   validationMsg.textContent = message;
147 |   cityInput.classList.add('is-invalid');
148 |   cityInput.setAttribute('aria-invalid', 'true');
149 | }
150 | 
151 | /** Remove any active validation error state. */
152 | function clearValidationError() {
153 |   validationMsg.textContent = '';
154 |   cityInput.classList.remove('is-invalid');
155 |   cityInput.removeAttribute('aria-invalid');
156 | }
157 | 
158 | /* ------------------------------------------------------------------ */
159 | /* 4. Search handler                                                   */
160 | /*                                                                     */
161 | /* Simulates an async data fetch with a short setTimeout so the       */
162 | /* loading state is visible during a demo walkthrough.                 */
163 | /* ------------------------------------------------------------------ */
164 | 
165 | /**
166 |  * Validate input, show loading, then render mock weather data.
167 |  */
168 | function handleSearch() {
169 |   const city = cityInput.value.trim();
170 | 
171 |   // Validate: city must not be empty
172 |   if (!city) {
173 |     showValidationError('Please enter a city name before searching.');
174 |     cityInput.focus();
175 |     return;
176 |   }
177 | 
178 |   clearValidationError();
179 |   setLoading(true);
180 | 
181 |   // Simulate a short network delay (300 ms) to exercise the loading state
182 |   setTimeout(function () {
183 |     const data = getMockWeather(city);
184 |     renderWeatherCard(data);
185 |     setLoading(false);
186 |     // Clear the input after a successful search for a clean UX
187 |     cityInput.value = '';
188 |   }, 300);
189 | }
190 | 
191 | /* ------------------------------------------------------------------ */
192 | /* 5. Event listeners                                                  */
193 | /* ------------------------------------------------------------------ */
194 | 
195 | // Form submission (button click or Enter key inside the input)
196 | searchForm.addEventListener('submit', function (event) {
197 |   event.preventDefault();
198 |   handleSearch();
199 | });
200 | 
201 | // Clear validation error as soon as the user starts typing again
202 | cityInput.addEventListener('input', function () {
203 |   if (cityInput.classList.contains('is-invalid')) {
204 |     clearValidationError();
205 |   }
206 | });
207 | 
208 | /* ------------------------------------------------------------------ */
209 | /* 6. Theme toggle                                                     */
210 | /*                                                                     */
211 | /* The theme is stored in localStorage under the key 'sdlc-theme'.   */
212 | /* On load we apply any saved preference before painting the page.    */
213 | /* ------------------------------------------------------------------ */
214 | 
215 | const THEME_STORAGE_KEY = 'sdlc-theme';
216 | const DARK_THEME        = 'dark';
217 | const LIGHT_THEME       = 'light';
218 | 
219 | /**
220 |  * Apply a theme to <body> and update the toggle button's accessible
221 |  * label and visible text.
222 |  *
223 |  * @param {'light'|'dark'} theme
224 |  */
225 | function applyTheme(theme) {
226 |   const isDark = theme === DARK_THEME;
227 |   document.body.setAttribute('data-theme', theme);
228 | 
229 |   // Update ARIA state and visible label so the button always describes
230 |   // what will happen next (i.e. "Switch to dark mode" when in light mode)
231 |   themeToggleBtn.setAttribute('aria-pressed', String(isDark));
232 |   themeToggleBtn.setAttribute('aria-label', isDark ? 'Switch to light mode' : 'Switch to dark mode');
233 |   themeToggleBtn.querySelector('.toggle-icon').textContent  = isDark ? '☀️' : '🌙';
234 |   themeToggleBtn.querySelector('.toggle-label').textContent = isDark ? 'Light' : 'Dark';
235 | }
236 | 
237 | /** Toggle between light and dark and persist the choice. */
238 | function toggleTheme() {
239 |   const current = document.body.getAttribute('data-theme') || LIGHT_THEME;
240 |   const next    = current === DARK_THEME ? LIGHT_THEME : DARK_THEME;
241 |   applyTheme(next);
242 |   localStorage.setItem(THEME_STORAGE_KEY, next);
243 | }
244 | 
245 | themeToggleBtn.addEventListener('click', toggleTheme);
246 | 
247 | /* ------------------------------------------------------------------ */
248 | /* 7. Initialisation                                                   */
249 | /*                                                                     */
250 | /* Runs once when the script is first parsed (deferred by placement   */
251 | /* at the bottom of <body>).  Restores saved theme and shows a        */
252 | /* default weather card so the page is never empty on first load.     */
253 | /* ------------------------------------------------------------------ */
254 | 
255 | (function init() {
256 |   // Restore saved theme preference (falls back to light)
257 |   const savedTheme = localStorage.getItem(THEME_STORAGE_KEY) || LIGHT_THEME;
258 |   applyTheme(savedTheme);
259 | 
260 |   // Show a default weather card for "New York" on first load
261 |   renderWeatherCard(getMockWeather('New York'));
262 | }());
263 |

Contents of file weather-app/styles.css:

1 | /* ===================================================================
2 |    styles.css – Weather Dashboard (SDLC Harness Demo)
3 |    All colours, spacing, and typography are controlled via CSS custom
4 |    properties so that the dark-mode override only needs a single block.
5 |    =================================================================== */
6 | 
7 | /* ------------------------------------------------------------------ */
8 | /* 1. CSS Custom Properties (design tokens)                            */
9 | /* ------------------------------------------------------------------ */
10 | :root {
11 |   /* Colours – light mode */
12 |   --color-bg:           #f0f4f8;
13 |   --color-surface:      #ffffff;
14 |   --color-surface-alt:  #e8edf2;
15 |   --color-border:       #d0d7de;
16 |   --color-text:         #1c2a3a;
17 |   --color-text-muted:   #4a5a6b;
18 |   --color-accent:       #1a6dbf;
19 |   --color-accent-hover: #145596;
20 |   --color-error:        #c0392b;
21 |   --color-error-bg:     #fdf0ee;
22 |   --color-spinner:      #1a6dbf;
23 | 
24 |   /* Spacing */
25 |   --space-xs:   0.25rem;
26 |   --space-sm:   0.5rem;
27 |   --space-md:   1rem;
28 |   --space-lg:   1.5rem;
29 |   --space-xl:   2rem;
30 |   --space-2xl:  3rem;
31 | 
32 |   /* Typography */
33 |   --font-family: -apple-system, "Segoe UI", system-ui, sans-serif;
34 |   --font-size-base: 1rem;
35 |   --font-size-sm:   0.875rem;
36 |   --font-size-lg:   1.25rem;
37 |   --font-size-xl:   1.75rem;
38 |   --font-size-2xl:  2.5rem;
39 |   --line-height:    1.6;
40 | 
41 |   /* Misc */
42 |   --radius:         0.5rem;
43 |   --radius-lg:      0.75rem;
44 |   --shadow:         0 2px 8px rgba(0,0,0,0.08);
45 |   --shadow-lg:      0 4px 20px rgba(0,0,0,0.12);
46 |   --transition:     0.2s ease;
47 |   --max-width:      720px;
48 | }
49 | 
50 | /* ------------------------------------------------------------------ */
51 | /* 2. Dark mode token overrides                                        */
52 | /*    Applied via the `data-theme="dark"` attribute on <body>,        */
53 | /*    which is toggled by app.js and persisted in localStorage.       */
54 | /* ------------------------------------------------------------------ */
55 | [data-theme="dark"] {
56 |   --color-bg:           #0d1117;
57 |   --color-surface:      #161b22;
58 |   --color-surface-alt:  #21262d;
59 |   --color-border:       #30363d;
60 |   --color-text:         #e6edf3;
61 |   --color-text-muted:   #8b949e;
62 |   --color-accent:       #58a6ff;
63 |   --color-accent-hover: #79b8ff;
64 |   --color-error:        #f85149;
65 |   --color-error-bg:     #1f1116;
66 |   --color-spinner:      #58a6ff;
67 |   --shadow:             0 2px 8px rgba(0,0,0,0.4);
68 |   --shadow-lg:          0 4px 20px rgba(0,0,0,0.6);
69 | }
70 | 
71 | /* ------------------------------------------------------------------ */
72 | /* 3. Base / Reset                                                     */
73 | /* ------------------------------------------------------------------ */
74 | *, *::before, *::after {
75 |   box-sizing: border-box;
76 |   margin: 0;
77 |   padding: 0;
78 | }
79 | 
80 | html {
81 |   font-size: 16px;
82 |   scroll-behavior: smooth;
83 | }
84 | 
85 | body {
86 |   font-family: var(--font-family);
87 |   font-size: var(--font-size-base);
88 |   line-height: var(--line-height);
89 |   background-color: var(--color-bg);
90 |   color: var(--color-text);
91 |   transition: background-color var(--transition), color var(--transition);
92 |   min-height: 100vh;
93 | }
94 | 
95 | /* Visible focus style – meets WCAG 2.4.11 */
96 | :focus-visible {
97 |   outline: 3px solid var(--color-accent);
98 |   outline-offset: 2px;
99 |   border-radius: 2px;
100 | }
101 | 
102 | /* Utility: visually hidden but accessible to screen readers */
103 | .visually-hidden {
104 |   position: absolute;
105 |   width: 1px;
106 |   height: 1px;
107 |   overflow: hidden;
108 |   clip: rect(0,0,0,0);
109 |   white-space: nowrap;
110 |   border: 0;
111 | }
112 | 
113 | /* Skip link */
114 | .skip-link {
115 |   position: absolute;
116 |   top: -100%;
117 |   left: var(--space-md);
118 |   background: var(--color-accent);
119 |   color: #fff;
120 |   padding: var(--space-sm) var(--space-md);
121 |   border-radius: var(--radius);
122 |   font-weight: 600;
123 |   text-decoration: none;
124 |   z-index: 9999;
125 | }
126 | .skip-link:focus {
127 |   top: var(--space-sm);
128 | }
129 | 
130 | /* ------------------------------------------------------------------ */
131 | /* 4. Page wrapper                                                     */
132 | /* ------------------------------------------------------------------ */
133 | .page-wrapper {
134 |   display: flex;
135 |   flex-direction: column;
136 |   min-height: 100vh;
137 | }
138 | 
139 | /* ------------------------------------------------------------------ */
140 | /* 5. Header                                                           */
141 | /* ------------------------------------------------------------------ */
142 | .site-header {
143 |   background-color: var(--color-surface);
144 |   border-bottom: 1px solid var(--color-border);
145 |   box-shadow: var(--shadow);
146 |   position: sticky;
147 |   top: 0;
148 |   z-index: 100;
149 | }
150 | 
151 | .header-inner {
152 |   max-width: var(--max-width);
153 |   margin: 0 auto;
154 |   padding: var(--space-md) var(--space-lg);
155 |   display: flex;
156 |   align-items: center;
157 |   justify-content: space-between;
158 |   gap: var(--space-md);
159 | }
160 | 
161 | .app-title {
162 |   font-size: var(--font-size-xl);
163 |   font-weight: 700;
164 |   color: var(--color-text);
165 |   letter-spacing: -0.02em;
