171 |   margin-top: var(--space-xs);
172 | }
173 | 
174 | /* Theme toggle button */
175 | .theme-toggle {
176 |   display: flex;
177 |   align-items: center;
178 |   gap: var(--space-xs);
179 |   background: var(--color-surface-alt);
180 |   border: 1px solid var(--color-border);
181 |   border-radius: var(--radius);
182 |   padding: var(--space-sm) var(--space-md);
183 |   font-size: var(--font-size-sm);
184 |   color: var(--color-text);
185 |   cursor: pointer;
186 |   transition: background var(--transition), border-color var(--transition);
187 |   white-space: nowrap;
188 | }
189 | .theme-toggle:hover {
190 |   background: var(--color-border);
191 | }
192 | 
193 | /* ------------------------------------------------------------------ */
194 | /* 6. Main content                                                     */
195 | /* ------------------------------------------------------------------ */
196 | .main-content {
197 |   flex: 1;
198 |   max-width: var(--max-width);
199 |   width: 100%;
200 |   margin: 0 auto;
201 |   padding: var(--space-xl) var(--space-lg);
202 |   display: flex;
203 |   flex-direction: column;
204 |   gap: var(--space-xl);
205 | }
206 | 
207 | /* ------------------------------------------------------------------ */
208 | /* 7. Search section                                                   */
209 | /* ------------------------------------------------------------------ */
210 | .search-form {
211 |   display: flex;
212 |   gap: var(--space-sm);
213 | }
214 | 
215 | .city-input {
216 |   flex: 1;
217 |   padding: var(--space-sm) var(--space-md);
218 |   font-size: var(--font-size-base);
219 |   font-family: var(--font-family);
220 |   border: 1px solid var(--color-border);
221 |   border-radius: var(--radius);
222 |   background: var(--color-surface);
223 |   color: var(--color-text);
224 |   transition: border-color var(--transition);
225 | }
226 | .city-input::placeholder {
227 |   color: var(--color-text-muted);
228 | }
229 | .city-input:focus {
230 |   border-color: var(--color-accent);
231 | }
232 | /* Validation error state – toggled by app.js */
233 | .city-input.is-invalid {
234 |   border-color: var(--color-error);
235 |   background: var(--color-error-bg);
236 | }
237 | 
238 | .search-btn {
239 |   padding: var(--space-sm) var(--space-lg);
240 |   font-size: var(--font-size-base);
241 |   font-family: var(--font-family);
242 |   font-weight: 600;
243 |   background: var(--color-accent);
244 |   color: #ffffff;
245 |   border: none;
246 |   border-radius: var(--radius);
247 |   cursor: pointer;
248 |   transition: background var(--transition);
249 |   white-space: nowrap;
250 | }
251 | .search-btn:hover {
252 |   background: var(--color-accent-hover);
253 | }
254 | .search-btn:disabled {
255 |   opacity: 0.65;
256 |   cursor: not-allowed;
257 | }
258 | 
259 | /* Validation message */
260 | .validation-message {
261 |   margin-top: var(--space-sm);
262 |   font-size: var(--font-size-sm);
263 |   color: var(--color-error);
264 |   min-height: 1.2em; /* reserve space so layout doesn't jump */
265 | }
266 | 
267 | /* ------------------------------------------------------------------ */
268 | /* 8. Card section & loading overlay                                   */
269 | /* ------------------------------------------------------------------ */
270 | .card-section {
271 |   position: relative;
272 | }
273 | 
274 | /* Loading overlay – briefly shown over the card when searching.
275 |    Use :not([hidden]) to set display:flex only when active, so the
276 |    CSS rule never overrides the HTML `hidden` attribute (which sets
277 |    display:none). Without this, display:flex wins and the spinner
278 |    stays visible even when hidden=true. */
279 | .loading-overlay {
280 |   position: absolute;
281 |   inset: 0;
282 |   background: rgba(255,255,255,0.75);
283 |   align-items: center;
284 |   justify-content: center;
285 |   gap: var(--space-sm);
286 |   border-radius: var(--radius-lg);
287 |   font-size: var(--font-size-sm);
288 |   color: var(--color-text-muted);
289 |   z-index: 10;
290 | }
291 | .loading-overlay:not([hidden]) {
292 |   display: flex;
293 | }
294 | [data-theme="dark"] .loading-overlay:not([hidden]) {
295 |   background: rgba(13,17,23,0.75);
296 | }
297 | 
