1 | /**
2 |  * onboard.ts — guided onboarding for the sdlc-harness skill (Task 18).
3 |  *
4 |  * Validation is deterministic. Persistence is explicit and atomic through
5 |  * `persistProjectConfig` so the CLI cannot leave a partially written config.
6 |  */
7 | 
8 | import * as crypto from 'crypto';
9 | import * as fs from 'fs';
10 | import * as path from 'path';
11 | import { inferStateForConcept } from '../agents/state-transition-agent';
12 | import type { WorkflowConcept } from '../agents/state-transition-agent';
13 | import type {
14 |   CoverageConfig,
15 |   ProjectConfig,
16 |   StateMapping,
17 |   TransitionRules,
18 | } from '../models';
19 | 
20 | // ---------------------------------------------------------------------------
21 | // Input / output shapes
22 | // ---------------------------------------------------------------------------
23 | 
24 | export interface OnboardInput {
25 |   projectUrl: string;
26 |   workItemTypes: string[];
27 |   workflowStates: string[];
28 |   transitionRules: TransitionRules;
29 |   /** Enable Premium/Ultimate directional blocking issue links. Defaults to false. */
30 |   blockingIssueLinks?: boolean;
31 |   /** Optional explicit aliases for custom workflow state names. */
32 |   stateMapping?: StateMapping;
33 |   /** Optional — pass only when the user explicitly opts in to coverage tracking (Task 24). */
34 |   coverage?: CoverageConfig;
35 | }
36 | 
37 | export interface OnboardResult {
38 |   ok: boolean;
39 |   config?: ProjectConfig;
40 |   error?: string;
41 | }
42 | 
43 | // ---------------------------------------------------------------------------
44 | // Validation helpers
45 | // ---------------------------------------------------------------------------
46 | 
47 | /** Return true for a plain object. */
48 | function isRecord(value: unknown): value is Record<string, unknown> {
49 |   return typeof value === 'object' && value !== null && !Array.isArray(value);
50 | }
51 | 
52 | /** Validate and canonicalize a GitLab project URL. */
53 | function normaliseProjectUrl(value: unknown): string {
54 |   if (typeof value !== 'string' || value.trim().length === 0) {
55 |     throw new Error('projectUrl is required and must not be empty.');
56 |   }
57 | 
58 |   let url: URL;
59 |   try {
60 |     url = new URL(value.trim());
61 |   } catch {
62 |     throw new Error('projectUrl must be a valid http or https URL.');
63 |   }
64 | 
65 |   if (url.protocol !== 'http:' && url.protocol !== 'https:') {
66 |     throw new Error('projectUrl must use http or https.');
67 |   }
68 |   if (url.username || url.password) {
69 |     throw new Error('projectUrl must not contain credentials.');
70 |   }
71 |   if (url.search) {
72 |     throw new Error('projectUrl must not contain a query string.');
73 |   }
74 |   if (url.hash) {
75 |     throw new Error('projectUrl must not contain a fragment.');
76 |   }
77 | 
78 |   const segments = url.pathname.split('/').filter((segment) => segment.length > 0);
79 |   if (segments.length < 2) {
80 |     throw new Error('projectUrl must include a GitLab namespace and project path.');
81 |   }
82 |   const projectIndex = segments.length - 1;
83 |   segments[projectIndex] = segments[projectIndex].replace(/\.git$/i, '');
84 |   if (segments[projectIndex].length === 0) {
85 |     throw new Error('projectUrl must include a GitLab namespace and project path.');
86 |   }
87 | 
88 |   return `${url.origin}/${segments.join('/')}`;
89 | }
90 | 
91 | /** Trim and case-insensitively deduplicate a required name list. */
92 | function normaliseNames(value: unknown, field: string): string[] {
93 |   if (!Array.isArray(value) || value.length === 0) {
94 |     throw new Error(`${field} must be a non-empty array of strings.`);
95 |   }
96 | 
97 |   const names: string[] = [];
98 |   const seen = new Set<string>();
99 |   for (const entry of value) {
100 |     if (typeof entry !== 'string' || entry.trim().length === 0) {
101 |       throw new Error(`${field} must not contain blank entries.`);
102 |     }
103 |     const name = entry.trim();
104 |     const key = name.toLowerCase();
105 |     if (seen.has(key)) continue;
106 |     seen.add(key);
107 |     names.push(name);
108 |   }
109 | 
110 |   return names;
111 | }
112 | 
113 | /** Validate transition arrays and canonicalize every direct edge. */
114 | function normaliseTransitionRules(value: unknown, states: string[]): TransitionRules {
115 |   if (!isRecord(value)) {
116 |     throw new Error('transitionRules must be an object whose values are arrays.');
117 |   }
118 | 
119 |   const names = new Map(states.map((state) => [state.toLowerCase(), state]));
120 |   const rules: TransitionRules = {};
121 |   for (const [rawFrom, rawTargets] of Object.entries(value)) {
122 |     const from = names.get(rawFrom.trim().toLowerCase());
123 |     if (!from) {
124 |       throw new Error(
125 |         `transitionRules contains unknown source state "${rawFrom}". ` +
126 |         `Valid states: ${states.join(', ')}.`,
127 |       );
128 |     }
129 | 
130 |     if (!Array.isArray(rawTargets)) {
131 |       throw new Error(`transitionRules[${rawFrom}] must be an array of state names.`);
132 |     }
133 | 
134 |     const targets = rules[from] ?? [];
135 |     const seen = new Set(targets.map((target) => target.toLowerCase()));
136 |     for (const rawTarget of rawTargets) {
137 |       if (typeof rawTarget !== 'string' || rawTarget.trim().length === 0) {
138 |         throw new Error(`transitionRules[${rawFrom}] must not contain blank entries.`);
139 |       }
140 |       const target = names.get(rawTarget.trim().toLowerCase());
141 |       if (!target) {
142 |         throw new Error(
143 |           `transitionRules[${rawFrom}] references unknown target state "${rawTarget}". ` +
144 |           `Valid states: ${states.join(', ')}.`,
145 |         );
146 |       }
147 |       if (target === from) {
148 |         throw new Error(`transitionRules[${rawFrom}] must not contain a self-transition.`);
149 |       }
150 |       if (seen.has(target.toLowerCase())) continue;
151 |       seen.add(target.toLowerCase());
152 |       targets.push(target);
153 |     }
154 |     rules[from] = targets;
155 |   }
156 | 
157 |   return rules;
158 | }
159 | 
160 | /** Validate optional workflow-concept mappings against configured states. */
161 | function normaliseStateMapping(value: unknown, states: string[]): StateMapping | undefined {
162 |   if (value !== undefined && !isRecord(value)) {
163 |     throw new Error('stateMapping must be an object.');
164 |   }
165 | 
166 |   const keys: WorkflowConcept[] = ['open', 'inProgress', 'inReview', 'done'];
167 |   const source = value ?? {};
168 |   const unknownKeys = Object.keys(source).filter(
169 |     (key) => !keys.includes(key as keyof StateMapping),
170 |   );
171 |   if (unknownKeys.length > 0) {
172 |     throw new Error(`stateMapping contains unknown key "${unknownKeys[0]}".`);
173 |   }
174 |   const names = new Map(states.map((state) => [state.toLowerCase(), state]));
175 |   const mapping: StateMapping = {};
176 |   const seen = new Set<string>();
177 | 
178 |   for (const key of keys) {
179 |     const rawState = source[key];
180 |     if (rawState === undefined) {
181 |       const inferred = inferStateForConcept(states, key);
182 |       if (!inferred) {
183 |         throw new Error(
184 |           `stateMapping.${key} is required because that workflow state cannot be inferred.`,
185 |         );
186 |       }
187 |       if (seen.has(inferred.toLowerCase())) {
188 |         throw new Error('Workflow concepts must resolve to distinct states.');
189 |       }
190 |       seen.add(inferred.toLowerCase());
191 |       continue;
192 |     }
193 |     if (typeof rawState !== 'string' || rawState.trim().length === 0) {
194 |       throw new Error(`stateMapping.${key} must be a non-blank state name.`);
195 |     }
196 |     const state = names.get(rawState.trim().toLowerCase());
197 |     if (!state) {
198 |       throw new Error(`stateMapping.${key} must reference a configured workflow state.`);
199 |     }
200 |     if (seen.has(state.toLowerCase())) {
201 |       throw new Error('stateMapping entries must reference distinct workflow states.');
202 |     }
203 |     seen.add(state.toLowerCase());
204 |     mapping[key] = state;
205 |   }
206 | 
207 |   return Object.keys(mapping).length === 0 ? undefined : mapping;
208 | }
209 | 
210 | /** Validate and normalize optional coverage scanning configuration. */
211 | function normaliseCoverage(value: unknown): CoverageConfig | undefined {
212 |   if (value === undefined) return undefined;
213 |   if (!isRecord(value) || typeof value['enabled'] !== 'boolean') {
214 |     throw new Error('coverage must contain a boolean enabled value.');
215 |   }
216 |   if (!Array.isArray(value['testFilePatterns'])) {
217 |     throw new Error('coverage.testFilePatterns must be an array of strings.');
218 |   }
219 | 
220 |   const patterns: string[] = [];
221 |   const seen = new Set<string>();
222 |   for (const entry of value['testFilePatterns']) {
223 |     if (typeof entry !== 'string' || entry.trim().length === 0) {
224 |       throw new Error('coverage.testFilePatterns must not contain blank entries.');
225 |     }
226 |     const pattern = entry.trim().replace(/\\/g, '/').replace(/^\.\/+/, '');
227 |     if (pattern.length === 0) {
228 |       throw new Error('coverage.testFilePatterns must not contain blank entries.');
229 |     }
230 |     if (path.isAbsolute(pattern) || path.win32.isAbsolute(pattern) ||
231 |         pattern.split('/').includes('..')) {
232 |       throw new Error('coverage.testFilePatterns must stay within the onboarded repo.');
233 |     }
234 |     if (seen.has(pattern)) continue;
235 |     seen.add(pattern);
236 |     patterns.push(pattern);
237 |   }
238 | 
239 |   if (value['enabled'] && patterns.length === 0) {
240 |     throw new Error('Enabled coverage requires at least one testFilePattern.');
241 |   }
242 | 
243 |   return { enabled: value['enabled'], testFilePatterns: patterns };
244 | }
245 | 
246 | /** Validate unknown data and return a normalized persisted configuration. */
247 | export function validateProjectConfig(value: unknown, requireProvider = true): ProjectConfig {
248 |   if (!isRecord(value)) throw new Error('Project configuration must be a JSON object.');
249 |   if (requireProvider && value['provider'] !== 'gitlab') {
250 |     throw new Error('Project configuration provider must be "gitlab".');
251 |   }
252 |   if (!requireProvider && value['provider'] !== undefined && value['provider'] !== 'gitlab') {
253 |     throw new Error('Only the "gitlab" project provider is supported.');
254 |   }
255 | 
256 |   const workItemTypes = normaliseNames(value['workItemTypes'], 'workItemTypes');
257 |   const workflowStates = normaliseNames(value['workflowStates'], 'workflowStates');
258 |   const transitionRules = normaliseTransitionRules(value['transitionRules'], workflowStates);
259 |   const stateMapping = normaliseStateMapping(value['stateMapping'], workflowStates);
260 |   const blockingIssueLinks = value['blockingIssueLinks'];
261 |   if (blockingIssueLinks !== undefined && typeof blockingIssueLinks !== 'boolean') {
262 |     throw new Error('blockingIssueLinks must be a boolean when provided.');
263 |   }
264 |   const coverage = normaliseCoverage(value['coverage']);
265 | 
266 |   return {
267 |     provider: 'gitlab',
268 |     projectUrl: normaliseProjectUrl(value['projectUrl']),
269 |     workItemTypes,
270 |     workflowStates,
271 |     transitionRules,
272 |     ...(blockingIssueLinks === undefined ? {} : { blockingIssueLinks }),
273 |     ...(stateMapping === undefined ? {} : { stateMapping }),
274 |     ...(coverage === undefined ? {} : { coverage }),
275 |   };
276 | }
277 | 
278 | // ---------------------------------------------------------------------------
279 | // onboard()
280 | // ---------------------------------------------------------------------------
281 | 
282 | /**
283 |  * Validate onboarding input and return a typed ProjectConfig.
284 |  *
285 |  * This is idempotent: calling it twice with the same valid input returns the
286 |  * same config without error. Use `persistProjectConfig` to save the result.
287 |  */
288 | export async function onboard(input: OnboardInput): Promise<OnboardResult> {
289 |   try {
290 |     return { ok: true, config: validateProjectConfig(input, false) };
291 |   } catch (error) {
292 |     return {
293 |       ok: false,
294 |       error: error instanceof Error ? error.message : 'Invalid project configuration.',
295 |     };
296 |   }
297 | }
298 | 
299 | /** Resolve the authoritative config path for live operations. */
300 | export function resolveProjectConfigPath(): string {
301 |   const configuredPath = process.env['SDLC_PROJECT_CONFIG'];
302 |   if (configuredPath) return path.resolve(configuredPath);
303 | 
304 |   const environmentPath = process.env['SDLC_ENV_FILE'];
305 |   if (environmentPath) {
306 |     return path.join(path.dirname(path.resolve(environmentPath)), '.sdlc-harness.json');
307 |   }
308 | 
309 |   return path.join(process.cwd(), '.sdlc-harness.json');
310 | }
311 | 
312 | /** Load and validate the authoritative project configuration. */
313 | export function loadProjectConfig(filePath = resolveProjectConfigPath()): ProjectConfig {
314 |   if (!fs.existsSync(filePath)) {
315 |     throw new Error(
316 |       `Project is not onboarded. Run "sdlc-harness onboard <config.json>" to create ${filePath}.`,
317 |     );
