  --color-bg:           #f0f4f8;
  --color-surface:      #ffffff;
  --color-surface-alt:  #e8edf2;
  --color-border:       #d0d7de;
  --color-text:         #1c2a3a;
  --color-text-muted:   #4a5a6b;
  --color-accent:       #1a6dbf;
  --color-accent-hover: #145596;
  --color-error:        #c0392b;
  --color-error-bg:     #fdf0ee;
  --color-spinner:      #1a6dbf;

  /* Spacing */
  --space-xs:   0.25rem;
  --space-sm:   0.5rem;
  --space-md:   1rem;
  --space-lg:   1.5rem;
  --space-xl:   2rem;
  --space-2xl:  3rem;

  /* Typography */
  --font-family: -apple-system, "Segoe UI", system-ui, sans-serif;
  --font-size-base: 1rem;
  --font-size-sm:   0.875rem;
  --font-size-lg:   1.25rem;
  --font-size-xl:   1.75rem;
  --font-size-2xl:  2.5rem;
  --line-height:    1.6;

  /* Misc */
  --radius:         0.5rem;
  --radius-lg:      0.75rem;
  --shadow:         0 2px 8px rgba(0,0,0,0.08);
  --shadow-lg:      0 4px 20px rgba(0,0,0,0.12);
  --transition:     0.2s ease;
  --max-width:      720px;
}

/* ------------------------------------------------------------------ */
/* 2. Dark mode token overrides                                        */
/*    Applied via the `data-theme="dark"` attribute on <body>,        */
/*    which is toggled by app.js and persisted in localStorage.       */
/* ------------------------------------------------------------------ */
[data-theme="dark"] {
  --color-bg:           #0d1117;
  --color-surface:      #161b22;
  --color-surface-alt:  #21262d;
  --color-border:       #30363d;
  --color-text:         #e6edf3;
  --color-text-muted:   #8b949e;
  --color-accent:       #58a6ff;
  --color-accent-hover: #79b8ff;
  --color-error:        #f85149;
  --color-error-bg:     #1f1116;
  --color-spinner:      #58a6ff;
  --shadow:             0 2px 8px rgba(0,0,0,0.4);
  --shadow-lg:          0 4px 20px rgba(0,0,0,0.6);
}

/* ------------------------------------------------------------------ */
/* 3. Base / Reset                                                     */
/* ------------------------------------------------------------------ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  line-height: var(--line-height);
  background-color: var(--color-bg);
  color: var(--color-text);
  transition: background-color var(--transition), color var(--transition);
  min-height: 100vh;
}

/* Visible focus style – meets WCAG 2.4.11 */
:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Utility: visually hidden but accessible to screen readers */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: var(--space-md);
  background: var(--color-accent);
  color: #fff;
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
}
