  box-shadow: var(--shadow);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: var(--space-md) var(--space-lg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-md);
}

.app-title {
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: -0.02em;
}

.app-subtitle {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
  margin-top: var(--space-xs);
}

/* Theme toggle button */
.theme-toggle {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  background: var(--color-surface-alt);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--space-sm) var(--space-md);
  font-size: var(--font-size-sm);
  color: var(--color-text);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  white-space: nowrap;
}
.theme-toggle:hover {
  background: var(--color-border);
}

/* ------------------------------------------------------------------ */
/* 6. Main content                                                     */
/* ------------------------------------------------------------------ */
.main-content {
  flex: 1;
  max-width: var(--max-width);
  width: 100%;
  margin: 0 auto;
  padding: var(--space-xl) var(--space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--space-xl);
}

/* ------------------------------------------------------------------ */
/* 7. Search section                                                   */
/* ------------------------------------------------------------------ */
.search-form {
  display: flex;
  gap: var(--space-sm);
}

.city-input {
  flex: 1;
  padding: var(--space-sm) var(--space-md);
  font-size: var(--font-size-base);
  font-family: var(--font-family);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  background: var(--color-surface);
  color: var(--color-text);
  transition: border-color var(--transition);
}
.city-input::placeholder {
  color: var(--color-text-muted);
}
.city-input:focus {
  border-color: var(--color-accent);
}
/* Validation error state – toggled by app.js */
.city-input.is-invalid {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}

.search-btn {
  padding: var(--space-sm) var(--space-lg);
  font-size: var(--font-size-base);
  font-family: var(--font-family);
  font-weight: 600;
  background: var(--color-accent);
  color: #ffffff;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition);
  white-space: nowrap;
}
.search-btn:hover {
  background: var(--color-accent-hover);
}
.search-btn:disabled {
  opacity: 0.65;
  cursor: not-allowed;
}

/* Validation message */
.validation-message {
  margin-top: var(--space-sm);
  font-size: var(--font-size-sm);
  color: var(--color-error);
  min-height: 1.2em; /* reserve space so layout doesn't jump */
}

/* ------------------------------------------------------------------ */
/* 8. Card section & loading overlay                                   */
/* ------------------------------------------------------------------ */
.card-section {
  position: relative;
}

/* Loading overlay – briefly shown over the card when searching.
   Use :not([hidden]) to set display:flex only when active, so the
   CSS rule never overrides the HTML `hidden` attribute (which sets
   display:none). Without this, display:flex wins and the spinner
   stays visible even when hidden=true. */
.loading-overlay {
  position: absolute;
  inset: 0;
  background: rgba(255,255,255,0.75);
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  border-radius: var(--radius-lg);
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
  z-index: 10;
}
.loading-overlay:not([hidden]) {
  display: flex;
}
[data-theme="dark"] .loading-overlay:not([hidden]) {
  background: rgba(13,17,23,0.75);
}

/* CSS spinner */
.spinner {
  width: 1.25rem;
  height: 1.25rem;
  border: 3px solid var(--color-border);
  border-top-color: var(--color-spinner);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

/* ------------------------------------------------------------------ */
/* 9. Weather card                                                     */
/* ------------------------------------------------------------------ */
.weather-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  padding: var(--space-xl);
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.card-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-sm);
}

.card-city {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  letter-spacing: -0.03em;
  color: var(--color-text);
}

.card-updated {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
}

.card-body {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.card-temp-block {
  display: flex;
  align-items: flex-start;
}

.card-temp {
  font-size: 4rem;
  font-weight: 300;
  line-height: 1;
  color: var(--color-accent);
}

.card-unit {
  font-size: var(--font-size-lg);
  color: var(--color-text-muted);
  margin-top: var(--space-sm);
}

.card-condition {
  font-size: var(--font-size-lg);
  color: var(--color-text-muted);
  font-style: italic;
}

/* Detail pairs (humidity, wind, AQI) */
.card-details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-md);
  background: var(--color-surface-alt);
  border-radius: var(--radius);
  padding: var(--space-md) var(--space-lg);
}

.card-detail-item {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

/* AQI row spans both columns */
.card-detail-item--full {
  grid-column: 1 / -1;
}

.card-detail-item dt {
  font-size: var(--font-size-sm);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-muted);
}

.card-detail-item dd {
  font-size: var(--font-size-lg);
  font-weight: 600;
  color: var(--color-text);
}

/* ------------------------------------------------------------------ */
/* 9b. AQI badge                                                       */
/* ------------------------------------------------------------------ */

.aqi-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-xs) var(--space-md);
  border-radius: var(--radius);
  font-size: var(--font-size-base);
  font-weight: 700;
  /* Default (no data) */
  background: var(--color-surface);
  color: var(--color-text-muted);
  border: 1px solid var(--color-border);
}

/* Good — AQI 0–50 */
.aqi-good {
  background: #d4edda;
  color: #155724;
  border-color: #c3e6cb;
}
[data-theme="dark"] .aqi-good {
  background: #1a3a24;
  color: #75d89e;
  border-color: #2d6a41;
}

/* Moderate — AQI 51–100 */
.aqi-moderate {
  background: #fff3cd;
  color: #856404;
  border-color: #ffeeba;
}
[data-theme="dark"] .aqi-moderate {
  background: #3a2f00;
  color: #ffd54f;
  border-color: #6b5200;
}

/* Unhealthy for Sensitive Groups — AQI 101–150 */
.aqi-usg {
  background: #fde3cc;
  color: #7a3b00;
  border-color: #f9c894;
}
[data-theme="dark"] .aqi-usg {
  background: #3a1c00;
  color: #ffb74d;
  border-color: #6b3600;
}

/* Unhealthy — AQI 151–300 */
.aqi-unhealthy {
  background: #f8d7da;
  color: #721c24;
  border-color: #f5c6cb;
}
[data-theme="dark"] .aqi-unhealthy {
  background: #3a0d12;
  color: #f48fb1;
  border-color: #6b1a22;
}

/* ------------------------------------------------------------------ */
/* 10. Footer                                                          */
/* ------------------------------------------------------------------ */
.site-footer {
  text-align: center;
  padding: var(--space-lg);
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
  border-top: 1px solid var(--color-border);
  background: var(--color-surface);
}

/* ------------------------------------------------------------------ */
/* 11. Responsive – mobile breakpoint                                  */
/* ------------------------------------------------------------------ */
@media (max-width: 600px) {
  .header-inner {
    padding: var(--space-md);
    flex-wrap: wrap;
  }

  .app-title {
    font-size: var(--font-size-lg);
  }

  .main-content {
    padding: var(--space-lg) var(--space-md);
  }

  .search-form {
    flex-direction: column;
  }

  .search-btn {
    width: 100%;
  }

  .card-city {
    font-size: var(--font-size-xl);
  }

  .card-temp {
    font-size: 3rem;
  }

  .card-details {
    grid-template-columns: 1fr;
  }
}

