353 |       assert(toolNames.includes(name), `listTools includes ${name}`);
354 |     }
355 | 
356 |     // 2. Verify each tool has a non-empty input schema (the core regression check).
357 |     //    Discriminated-union schemas produce anyOf, not properties — accept either.
358 |     for (const tool of tools) {
359 |       const schema = tool.inputSchema as {
360 |         anyOf?: unknown[];
361 |         oneOf?: unknown[];
362 |         properties?: Record<string, unknown>;
363 |       };
364 |       const hasContent =
365 |         schema &&
366 |         typeof schema === "object" &&
367 |         (
368 |           (Array.isArray(schema.anyOf) && schema.anyOf.length > 0) ||
369 |           (Array.isArray(schema.oneOf) && schema.oneOf.length > 0) ||
370 |           ("properties" in schema && Object.keys(schema.properties ?? {}).length > 0)
371 |         );
