1 | /**
2 |  * index.ts — MCP server entry point for sdlc-harness.
3 |  *
4 |  * Startup sequence:
5 |  *  1. Load configuration from the env file (throws with a clear message if
6 |  *     required variables are missing).
7 |  *  2. Construct the GitLab client with the loaded config.
8 |  *  3. Build the shared ToolContext.
9 |  *  4. Create a low-level Server, register ListTools + CallTool handlers so that
10 |  *     discriminated-union Zod schemas are published as proper JSON object Schemas.
11 |  *  5. Connect via StdioServerTransport and stay running.
12 |  *
13 |  * Why the low-level Server rather than McpServer?
14 |  *  McpServer.registerTool() calls normalizeObjectSchema() internally, which only
15 |  *  handles z.object() schemas (those with a `.shape` property). Discriminated
16 |  *  unions expose no `.shape`, so the SDK falls back to publishing an empty
17 |  *  inputSchema for every tool. Using the low-level Server lets us build the
18 |  *  inputSchema ourselves.
19 |  *
20 |  * Why not emit anyOf from zodToJsonSchema?
21 |  *  The MCP protocol requires inputSchema.type === "object" strictly (validated
22 |  *  by the SDK's Zod schema on the ListTools result). We flatten the discriminated
23 |  *  union into a single object schema: all per-variant properties merged with
24 |  *  everything optional, plus an `action` enum listing all valid discriminator
25 |  *  values. This satisfies the protocol and gives hosts enough information to
26 |  *  drive tool calls correctly.
27 |  *
28 |  * Stderr is kept quiet unless SDLC_DEBUG=true so Bob's stdio transport
29 |  * is not polluted with log noise.
30 |  */
31 | 
32 | import { Server } from "@modelcontextprotocol/sdk/server/index.js";
33 | import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
34 | import {
35 |   ListToolsRequestSchema,
36 |   CallToolRequestSchema,
37 |   ErrorCode,
38 |   McpError,
39 | } from "@modelcontextprotocol/sdk/types.js";
40 | import { ZodTypeAny } from "zod";
41 | import { zodToJsonSchema } from "zod-to-json-schema";
42 | import { loadConfig, debugLog } from "./env.js";
43 | import { GitLabClient } from "./gitlab-client.js";
44 | import { TOOLS } from "./tools.js";
45 | import type { ToolContext } from "./types.js";
46 | 
47 | // ---------------------------------------------------------------------------
48 | // Schema flattening — discriminated union → MCP-compatible object schema
49 | // ---------------------------------------------------------------------------
50 | 
51 | /**
52 |  * The MCP protocol requires inputSchema to be a JSON Schema object with
53 |  * type === "object". zodToJsonSchema produces anyOf for discriminated unions,
54 |  * which the SDK's Zod validator rejects on the ListTools response.
55 |  *
56 |  * This function flattens a Zod discriminated union into a single object schema:
57 |  *  - All properties from all variants are merged (each made optional).
58 |  *  - The discriminator field ("action") becomes an enum of all literal values.
59 |  *  - "action" is the only required field.
60 |  *
61 |  * The result is valid per the MCP spec and gives the host sufficient information
62 |  * to construct valid tool calls.
63 |  */
64 | function buildInputSchema(schema: ZodTypeAny): Record<string, unknown> {
65 |   // Handle discriminated unions
66 |   const def = (schema as { _def?: { typeName?: string; options?: ZodTypeAny[]; discriminator?: string } })._def;
67 |   if (def?.typeName === "ZodDiscriminatedUnion" && Array.isArray(def.options)) {
68 |     const discriminator = def.discriminator ?? "action";
69 |     const mergedProperties: Record<string, unknown> = {};
70 |     const actionLiterals: string[] = [];
71 | 
72 |     for (const variant of def.options as ZodTypeAny[]) {
73 |       const variantDef = (variant as { _def?: { typeName?: string; shape?: () => Record<string, ZodTypeAny> } })._def;
74 |       if (!variantDef?.shape) continue;
75 |       const shape = typeof variantDef.shape === "function" ? variantDef.shape() : variantDef.shape;
76 |       for (const [key, fieldSchema] of Object.entries(shape as Record<string, ZodTypeAny>)) {
77 |         if (key === discriminator) {
78 |           // Collect all literal values for the discriminator enum
79 |           const litDef = (fieldSchema as { _def?: { value?: string } })._def;
80 |           if (litDef?.value !== undefined) {
81 |             actionLiterals.push(litDef.value as string);
82 |           }
83 |         } else if (!(key in mergedProperties)) {
84 |           // Add field as optional (any variant may or may not supply it)
85 |           const fieldJson = zodToJsonSchema(fieldSchema, { $refStrategy: "none" }) as Record<string, unknown>;
86 |           const { $schema: _omit, ...fieldJsonClean } = fieldJson;
87 |           mergedProperties[key] = fieldJsonClean;
88 |         }
89 |       }
90 |     }
91 | 
92 |     // Build merged discriminator field
93 |     mergedProperties[discriminator] = actionLiterals.length > 0
94 |       ? { type: "string", enum: actionLiterals, description: `Tool action. One of: ${actionLiterals.join(", ")}` }
95 |       : { type: "string" };
96 | 
97 |     return {
98 |       type: "object",
99 |       properties: mergedProperties,
100 |       required: [discriminator],
101 |     };
102 |   }
103 | 
104 |   // Fallback: use zodToJsonSchema directly (handles plain z.object())
105 |   const js = zodToJsonSchema(schema, { $refStrategy: "none" }) as Record<string, unknown>;
106 |   const { $schema: _omit, ...clean } = js;
107 |   return clean;
108 | }
109 | 
110 | // ---------------------------------------------------------------------------
111 | // Server startup
112 | // ---------------------------------------------------------------------------
113 | 
114 | async function main(): Promise<void> {
115 |   // 1. Load + validate configuration
116 |   const config = loadConfig();
117 |   debugLog(config, "Configuration loaded successfully.");
118 | 
119 |   // 2. Construct GitLab client
120 |   const gitlab = new GitLabClient(
121 |     config.gitlabHost,
122 |     config.gitlabToken,
123 |     config.gitlabProject
124 |   );
125 |   debugLog(config, `GitLab client ready for project: ${config.gitlabProject}`);
126 | 
127 |   // 3. Build shared context
128 |   const context: ToolContext = { gitlab, config };
129 | 
130 |   // 4. Pre-build MCP-compatible input schemas for all tools
131 |   const toolInputSchemas = new Map(
132 |     TOOLS.map((tool) => [tool.name, buildInputSchema(tool.argsSchema)])
133 |   );
134 | 
135 |   // 5. Create low-level MCP server and register tool handlers
136 |   const server = new Server(
137 |     { name: "sdlc-harness", version: "0.1.0" },
138 |     { capabilities: { tools: {} } }
139 |   );
140 | 
141 |   // ListTools — return all registered tools with their MCP-compatible schemas
142 |   server.setRequestHandler(ListToolsRequestSchema, () => ({
143 |     tools: TOOLS.map((tool) => ({
144 |       name: tool.name,
145 |       description: tool.description,
146 |       inputSchema: toolInputSchemas.get(tool.name)!,
147 |     })),
148 |   }));
149 | 
150 |   // CallTool — parse args with the full Zod discriminated union, execute
151 |   server.setRequestHandler(CallToolRequestSchema, async (request) => {
152 |     const { name, arguments: args } = request.params;
153 | 
154 |     const tool = TOOLS.find((t) => t.name === name);
155 |     if (!tool) {
156 |       throw new McpError(ErrorCode.MethodNotFound, `Tool not found: ${name}`);
157 |     }
158 | 
159 |     const parseResult = tool.argsSchema.safeParse(args ?? {});
160 |     if (!parseResult.success) {
161 |       throw new McpError(
162 |         ErrorCode.InvalidParams,
163 |         `Invalid arguments for tool ${name}: ${parseResult.error.message}`
164 |       );
165 |     }
166 | 
167 |     const result = await tool.execute(parseResult.data, context);
168 |     return {
169 |       content: [
170 |         {
171 |           type: "text" as const,
172 |           text: JSON.stringify(result, null, 2),
173 |         },
174 |       ],
175 |     };
176 |   });
177 | 
178 |   debugLog(config, `${TOOLS.length} tool(s) registered. Connecting transport...`);
179 | 
180 |   // 6. Connect stdio transport and keep the process alive
181 |   const transport = new StdioServerTransport();
182 |   await server.connect(transport);
183 | 
184 |   debugLog(config, "MCP server connected and listening on stdio.");
185 | }
186 | 
187 | main().catch((error: unknown) => {
188 |   const message = error instanceof Error ? error.message : String(error);
189 |   process.stderr.write(`[sdlc-harness] Fatal startup error: ${message}\n`);
190 |   process.exit(1);
191 | });
