1 | /**
2 |  * env.ts — safe configuration loading for the sdlc-harness MCP server.
3 |  *
4 |  * Rules:
5 |  *  - Reads from a dotenv file ONLY if the variable is not already set in
6 |  *    the process environment (never overrides).
7 |  *  - Never logs or echoes credential values.
8 |  *  - The env-file path itself can be overridden via SDLC_ENV_FILE so the
9 |  *    server can be pointed at different environments without code changes.
10 |  *  - Throws a descriptive error listing every missing required variable so
11 |  *    the operator knows exactly what to fix.
12 |  */
13 | 
14 | import { readFileSync } from "fs";
15 | import { resolve } from "path";
16 | 
17 | // ---------------------------------------------------------------------------
18 | // Resolved configuration shape
19 | // ---------------------------------------------------------------------------
20 | 
21 | /** All runtime configuration consumed by the MCP server. */
22 | export interface Config {
23 |   /** GitLab instance host, e.g. "https://gitlab.example.com". No trailing slash. */
24 |   gitlabHost: string;
25 | 
26 |   /** GitLab project path (e.g. "sdlc-harness-demo/weather") or numeric ID. */
27 |   gitlabProject: string;
28 | 
29 |   /** GitLab Personal Access Token with api scope. */
30 |   gitlabToken: [REDACTED]
31 | 
32 |   /** Emit verbose debug output to stderr when true. */
33 |   debug: boolean;
34 | }
35 | 
36 | // ---------------------------------------------------------------------------
37 | // Dotenv file parser — avoids a runtime dependency on the dotenv binary
38 | // ---------------------------------------------------------------------------
39 | 
40 | /**
41 |  * Parse a .env file and return key/value pairs.
42 |  * Lines starting with # and blank lines are ignored.
43 |  * Values may be quoted with single or double quotes (quotes are stripped).
44 |  */
45 | function parseDotenvFile(filePath: string): Record<string, string> {
46 |   let raw: string;
47 |   try {
48 |     raw = readFileSync(filePath, "utf-8");
49 |   } catch {
50 |     // File is optional — return empty record if it doesn't exist
51 |     return {};
52 |   }
53 | 
54 |   const result: Record<string, string> = {};
55 |   for (const line of raw.split(/\r?\n/)) {
56 |     const trimmed = line.trim();
57 |     if (!trimmed || trimmed.startsWith("#")) continue;
58 | 
59 |     const eqIndex = trimmed.indexOf("=");
60 |     if (eqIndex === -1) continue;
61 | 
62 |     const key = trimmed.slice(0, eqIndex).trim();
63 |     let value = trimmed.slice(eqIndex + 1).trim();
64 | 
65 |     // Strip surrounding quotes
66 |     if (
67 |       (value.startsWith('"') && value.endsWith('"')) ||
68 |       (value.startsWith("'") && value.endsWith("'"))
69 |     ) {
70 |       value = value.slice(1, -1);
71 |     }
72 | 
73 |     result[key] = value;
74 |   }
75 |   return result;
76 | }
77 | 
78 | // ---------------------------------------------------------------------------
79 | // Public API
80 | // ---------------------------------------------------------------------------
81 | 
82 | /**
83 |  * Load and validate configuration.
84 |  *
85 |  * 1. Determines the env-file path (SDLC_ENV_FILE env var → default ".env").
86 |  * 2. Reads the file and merges into process.env — existing vars win.
87 |  * 3. Validates required vars are present and returns a typed Config object.
88 |  *
89 |  * Throws if any required variable is missing.
90 |  * Never logs values — only variable names.
91 |  */
92 | export function loadConfig(): Config {
93 |   // Determine env-file location
94 |   const envFilePath = resolve(
95 |     process.env["SDLC_ENV_FILE"] ?? ".env"
96 |   );
97 | 
98 |   // Parse file (silently skipped if absent)
99 |   const fileVars = parseDotenvFile(envFilePath);
100 | 
101 |   // Merge into process.env WITHOUT overriding existing values
102 |   for (const [key, value] of Object.entries(fileVars)) {
103 |     if (process.env[key] === undefined) {
104 |       process.env[key] = value;
105 |     }
106 |   }
107 | 
108 |   // Validate required variables
109 |   const required = [
110 |     "GITLAB_HOST",
111 |     "GITLAB_PROJECT",
112 |     "GITLAB_TOKEN",
113 |   ] as const;
114 | 
115 |   const missing = required.filter((key) => !process.env[key]);
116 | 
117 |   if (missing.length > 0) {
118 |     throw new Error(
119 |       `Missing required environment variables: ${missing.join(", ")}\n` +
120 |       `Set them in your .env file or in the process environment.\n` +
121 |       `See .env.example for the expected variable names.`
122 |     );
123 |   }
124 | 
125 |   return {
126 |     gitlabHost: process.env["GITLAB_HOST"]!.replace(/\/$/, ""),
127 |     gitlabProject: process.env["GITLAB_PROJECT"]!,
128 |     gitlabToken: [REDACTED],
129 |     debug: process.env["SDLC_DEBUG"] === "true" || process.env["SDLC_DEBUG"] === "1",
130 |   };
131 | }
132 | 
133 | /**
134 |  * Emit a debug message to stderr.
135 |  * Only produces output when config.debug is true.
136 |  * NEVER call this with a token or credential value.
137 |  */
138 | export function debugLog(config: Config, message: string): void {
139 |   if (config.debug) {
140 |     process.stderr.write(`[sdlc-harness debug] ${message}\n`);
141 |   }
142 | }
