1 | /**
2 |  * gitlab-client.ts — GitLab REST API client for sdlc-harness.
3 |  *
4 |  * Design goals:
5 |  *  - Thin wrapper: one method per API operation needed by the tools.
6 |  *  - Testable: the class is constructed with a host + token so tests can
7 |  *    substitute fixture responses by swapping the underlying fetch function.
8 |  *  - No retries or pagination helpers here — keep it simple for the MVP.
9 |  *    Pagination is handled per-call by passing `per_page` and `page` params.
10 |  *
11 |  * All methods throw a GitLabApiError on non-2xx responses so callers get
12 |  * structured error info (status, message) rather than raw fetch rejections.
13 |  */
14 | 
15 | import type {
16 |   GitLabIssue,
17 |   GitLabLabel,
18 |   GitLabMR,
19 |   GitLabNote,
20 |   CreateIssueParams,
21 |   UpdateIssueParams,
22 |   CreateMRParams,
23 |   UpdateMRParams,
24 | } from "./types.js";
25 | 
26 | // ---------------------------------------------------------------------------
27 | // Error type
28 | // ---------------------------------------------------------------------------
29 | 
30 | /** Thrown when the GitLab API returns a non-2xx status. */
31 | export class GitLabApiError extends Error {
32 |   constructor(
33 |     public readonly status: number,
34 |     public readonly endpoint: string,
35 |     message: string
36 |   ) {
37 |     super(`GitLab API error ${status} on ${endpoint}: ${message}`);
38 |     this.name = "GitLabApiError";
39 |   }
40 | }
41 | 
42 | // ---------------------------------------------------------------------------
43 | // Fetch abstraction — injectable for tests
44 | // ---------------------------------------------------------------------------
45 | 
46 | /** Minimal fetch interface so tests can supply a mock. */
47 | export type FetchFn = (url: string, init?: RequestInit) => Promise<Response>;
48 | 
49 | // ---------------------------------------------------------------------------
50 | // GitLabClient
51 | // ---------------------------------------------------------------------------
52 | 
53 | export class GitLabClient {
54 |   private readonly baseUrl: string;
55 |   private readonly headers: Record<string, string>;
56 |   private readonly fetch: FetchFn;
57 | 
58 |   /**
59 |    * @param host        GitLab host, e.g. "https://gitlab.example.com". No trailing slash.
60 |    * @param token       Personal Access Token with `api` scope.
61 |    * @param projectPath Project path or numeric ID, e.g. "mygroup/myproject".
62 |    * @param fetchFn     Optional fetch override — defaults to global fetch (Node ≥18).
63 |    */
64 |   constructor(
65 |     host: string,
66 |     token: string,
67 |     public readonly projectPath: string,
68 |     fetchFn?: FetchFn
69 |   ) {
70 |     this.baseUrl = `${host}/api/v4`;
71 |     this.headers = {
72 |       "PRIVATE-TOKEN": token,
73 |       "Content-Type": "application/json",
74 |     };
75 |     // Node 18+ ships with global fetch; tests can inject a mock
76 |     this.fetch = fetchFn ?? (globalThis.fetch as FetchFn);
77 |   }
78 | 
79 |   // -------------------------------------------------------------------------
80 |   // Internal helpers
81 |   // -------------------------------------------------------------------------
82 | 
83 |   /** URL-encode a project path (slashes → %2F) for use in API endpoints. */
84 |   private encodedProject(): string {
85 |     return encodeURIComponent(this.projectPath);
86 |   }
87 | 
88 |   /** Build a full API URL for a project-scoped path. */
89 |   private projectUrl(path: string): string {
90 |     return `${this.baseUrl}/projects/${this.encodedProject()}${path}`;
91 |   }
92 | 
93 |   /**
94 |    * Execute an API request and return the parsed JSON body.
