+// ---------------------------------------------------------------------------
+// Test suite: config loading
+// ---------------------------------------------------------------------------
+
+async function testConfigLoading(): Promise<void> {
+  section("Config loading");
+
+  // Existing environment values win over .env file values
+  const originalHost = process.env["GITLAB_HOST"];
+  const originalProject = process.env["GITLAB_PROJECT"];
+  const originalToken = [REDACTED];
+
+  process.env["GITLAB_HOST"] = "https://existing.example.com";
+  process.env["GITLAB_PROJECT"] = "existing/project";
+  process.env["GITLAB_TOKEN"] = "existing-token";
+
+  // Point at a non-existent env file so we can't accidentally load from disk
+  process.env["SDLC_ENV_FILE"] = "/tmp/does-not-exist-smoke-test.env";
+
+  const { loadConfig } = await import("./env.js");
+  const config = loadConfig();
+
+  assert(config.gitlabHost === "https://existing.example.com", "Existing env values win over env file");
+  assert(config.gitlabProject === "existing/project", "Existing project env value preserved");
+
+  // Restore
+  if (originalHost !== undefined) process.env["GITLAB_HOST"] = originalHost;
+  else delete process.env["GITLAB_HOST"];
+  if (originalProject !== undefined) process.env["GITLAB_PROJECT"] = originalProject;
+  else delete process.env["GITLAB_PROJECT"];
+  if (originalToken !== undefined) process.env["GITLAB_TOKEN"] = originalToken;
+  else delete process.env["GITLAB_TOKEN"];
+  delete process.env["SDLC_ENV_FILE"];
+
+  // Missing variables produce a safe error (no credential in message)
+  const savedHost = process.env["GITLAB_HOST"];
+  const savedProject = process.env["GITLAB_PROJECT"];
+  const savedToken = [REDACTED];
+  delete process.env["GITLAB_HOST"];
+  delete process.env["GITLAB_PROJECT"];
+  delete process.env["GITLAB_TOKEN"];
+  process.env["SDLC_ENV_FILE"] = "/tmp/does-not-exist-smoke-test.env";
+
+  let caughtMsg = "";
+  try {
+    loadConfig();
+  } catch (err) {
+    caughtMsg = err instanceof Error ? err.message : String(err);
+  }
+  assert(caughtMsg.includes("Missing required"), "Missing variables produce a descriptive error");
+  // Credentials must never be logged — the error message should not contain token values
+  assert(!caughtMsg.includes("existing-token"), "Error message does not log credential values");
+
+  // Restore
+  if (savedHost !== undefined) process.env["GITLAB_HOST"] = savedHost;
+  if (savedProject !== undefined) process.env["GITLAB_PROJECT"] = savedProject;
+  if (savedToken !== undefined) process.env["GITLAB_TOKEN"] = savedToken;
+  delete process.env["SDLC_ENV_FILE"];
+}
