+#!/usr/bin/env node
+/**
+ * merge-bob-config.mjs — MERGE-ONLY installer for Bob global config.
+ *
+ * Bob's configuration lives in ~/.bob/settings/:
+ *   - mcp.json              : MCP server registrations
+ *   - custom_modes.yaml     : custom Bob modes
+ *
+ * This script merges the sdlc-harness entries INTO those files without
+ * overwriting unrelated existing config. It is safe to run multiple times
+ * (idempotent — re-running is a no-op if already installed).
+ *
+ * Safety rules:
+ *  - Never overwrites a file that cannot be parsed (exits non-zero instead).
+ *  - All writes go through a temp file + atomic rename to prevent partial writes.
+ *  - Preserves ALL unrelated entries in both files.
+ *  - Uses bob-kit/custom_modes.yaml as the authoritative source for the mode def.
+ *  - The MCP server entry name is always "sdlc-harness" (no gitlab-local aliases).
+ *
+ * Usage (from the mcp-server directory):
+ *   node merge-bob-config.mjs [<projectRoot>]
+ * Or via install.sh which calls it automatically.
+ */
+
+import {
+  readFileSync,
+  writeFileSync,
+  existsSync,
+  mkdirSync,
+  renameSync,
+} from "fs";
+import { join } from "path";
+import { homedir, tmpdir } from "os";
+
+const BOB_DIR = join(homedir(), ".bob");
+const BOB_SETTINGS_DIR = join(BOB_DIR, "settings");
+const MCP_JSON_PATH = join(BOB_SETTINGS_DIR, "mcp.json");
+const MODES_YAML_PATH = join(BOB_SETTINGS_DIR, "custom_modes.yaml");
+
+// ---------------------------------------------------------------------------
+// Minimal YAML helpers — only what we need to upsert the mode entry
+// ---------------------------------------------------------------------------
+
+/**
+ * Parse a YAML document that is a top-level mapping with a "customModes" key
+ * whose value is a sequence of mode objects, each with a "slug" string.
+ *
+ * Returns null if the document cannot be parsed safely (caller must abort).
+ *
+ * NOTE: This is a purpose-built parser for the known Bob modes YAML structure
+ * only. It does NOT handle arbitrary YAML.
+ */
+function parseModesYaml(text) {
+  // Quick sanity check: must start with optional comments/blank lines then
+  // "customModes:" at the start of a line.
+  if (!/^customModes\s*:/m.test(text)) {
+    // Could be empty file or already a bare list — accept bare list too
+    if (text.trim() === "" || text.trim().startsWith("-")) {
+      return { customModes: [] };
+    }
+    return null; // unrecognised structure
+  }
+  // Extract all slug values by scanning for "- slug: <value>" patterns.
+  // We don't reconstruct the full object tree — we only need slugs for the
+  // idempotency check.
+  const slugs = [];
+  const slugRe = /^\s+-\s+slug\s*:\s*(.+)/gm;
+  let m;
+  while ((m = slugRe.exec(text)) !== null) {
+    slugs.push(m[1].trim().replace(/^["']|["']$/g, ""));
+  }
+  return { customModes: slugs.map((s) => ({ slug: s })) };
+}
+
+/**
+ * Upsert a mode block into existing YAML text.
+ *
+ * If a mode with the given slug already exists: no-op (return original text).
+ * If the customModes: list is present: append the new block inside it.
+ * Otherwise: initialise with customModes: header + the new block.
+ */
+function upsertModeYaml(existingText, slug, modeBlock) {
+  if (existingText.includes(`slug: ${slug}`)) {
+    return existingText; // already present — idempotent
+  }
+
+  if (/^customModes\s*:/m.test(existingText)) {
+    // Append to the existing customModes list
+    return existingText.trimEnd() + "\n" + modeBlock + "\n";
+  }
+
+  if (existingText.trim() === "" || existingText.trim().startsWith("-")) {
+    // File is empty or a bare list — wrap in customModes:
+    const preamble = "# sdlc-harness custom modes — managed by merge-bob-config.mjs\ncustomModes:\n";
+    const existing = existingText.trim() ? existingText.trim() + "\n" : "";
+    return preamble + existing + modeBlock + "\n";
+  }
+
+  return existingText.trimEnd() + "\n" + modeBlock + "\n";
+}
+
+// ---------------------------------------------------------------------------
+// Atomic write helper
+// ---------------------------------------------------------------------------
+
+function atomicWrite(targetPath, content) {
+  const tmp = join(tmpdir(), `bob-config-${Date.now()}-${Math.random().toString(36).slice(2)}.tmp`);
+  writeFileSync(tmp, content, "utf-8");
+  renameSync(tmp, targetPath);
+}
+
+// ---------------------------------------------------------------------------
+// Helpers
+// ---------------------------------------------------------------------------
+
+function ensureDir(dir) {
+  if (!existsSync(dir)) {
+    mkdirSync(dir, { recursive: true });
+    console.log(`Created directory: ${dir}`);
+  }
+}
+
+// ---------------------------------------------------------------------------
+// mcp.json merge
+// ---------------------------------------------------------------------------
+
+function mergeMcpJson(absoluteProjectPath) {
+  let existing = {};
+
+  if (existsSync(MCP_JSON_PATH)) {
+    let raw;
+    try {
+      raw = readFileSync(MCP_JSON_PATH, "utf-8");
+    } catch (e) {
+      console.error(`Error: cannot read ${MCP_JSON_PATH}: ${e.message}`);
+      process.exit(1);
+    }
+    try {
+      existing = JSON.parse(raw);
+    } catch (e) {
+      console.error(`Error: ${MCP_JSON_PATH} contains invalid JSON — aborting to protect existing config.`);
+      console.error(`  Parse error: ${e.message}`);
+      process.exit(1);
+    }
+  }
+
+  // Support both "mcpServers" (Bob's key) and "servers" (legacy key)
+  const servers = existing.mcpServers ?? existing.servers ?? {};
+
+  if (servers["sdlc-harness"]) {
+    console.log(`✓ sdlc-harness already present in mcp.json — skipping.`);
+    return;
+  }
+
+  // Resolve absolute paths
+  const indexPath = join(absoluteProjectPath, "bob-kit", "mcp-server", "dist", "index.js");
+  const envPath = join(absoluteProjectPath, ".env");
+
+  const newEntry = {
+    type: "stdio",
+    command: "node",
+    args: [indexPath],
+    env: {
+      SDLC_ENV_FILE: envPath,
+    },
+  };
+
+  const merged = {
+    ...existing,
+    mcpServers: {
+      ...servers,
+      "sdlc-harness": newEntry,
+    },
+  };
+
+  atomicWrite(MCP_JSON_PATH, JSON.stringify(merged, null, 2) + "\n");
+  console.log(`✓ Merged sdlc-harness into ${MCP_JSON_PATH}`);
+}
+
+// ---------------------------------------------------------------------------
+// custom_modes.yaml merge — reads source from bob-kit/custom_modes.yaml
+// ---------------------------------------------------------------------------
+
+function mergeModes(absoluteProjectPath) {
+  // Read the authoritative mode definition from bob-kit/custom_modes.yaml
+  const sourceFile = join(absoluteProjectPath, "bob-kit", "custom_modes.yaml");
+  if (!existsSync(sourceFile)) {
+    console.warn(`Warning: ${sourceFile} not found — skipping mode merge.`);
+    return;
+  }
+
+  let sourceText;
+  try {
+    sourceText = readFileSync(sourceFile, "utf-8");
+  } catch (e) {
+    console.error(`Error: cannot read ${sourceFile}: ${e.message}`);
+    process.exit(1);
+  }
+
+  // Extract the mode block for sdlc-harness from the source file.
+  // The source file starts with a comment + "customModes:" header.
+  // We want the YAML text for the sdlc-harness entry only.
+  const modeBlockMatch = sourceText.match(/(\s+-\s+slug\s*:\s*sdlc-harness[\s\S]*?)(?=\n\s+-\s+slug\s*:|$)/);
+  if (!modeBlockMatch) {
+    console.warn(`Warning: sdlc-harness mode entry not found in ${sourceFile} — skipping.`);
+    return;
+  }
+  const modeBlock = modeBlockMatch[1].trimEnd();
+
+  // Read existing modes file (if present)
+  let existingText = "";
+  if (existsSync(MODES_YAML_PATH)) {
+    try {
+      existingText = readFileSync(MODES_YAML_PATH, "utf-8");
+    } catch (e) {
+      console.error(`Error: cannot read ${MODES_YAML_PATH}: ${e.message}`);
+      process.exit(1);
+    }
+
+    // Validate the existing file is parseable before touching it
+    const parsed = parseModesYaml(existingText);
+    if (parsed === null) {
+      console.error(`Error: ${MODES_YAML_PATH} has an unrecognised structure — aborting to protect existing config.`);
+      process.exit(1);
+    }
+  }
+
+  if (existingText.includes("slug: sdlc-harness")) {
+    console.log(`✓ sdlc-harness mode already present in custom_modes.yaml — skipping.`);
+    return;
+  }
+
+  const updated = upsertModeYaml(existingText, "sdlc-harness", modeBlock);
+  atomicWrite(MODES_YAML_PATH, updated);
+  console.log(`✓ Merged sdlc-harness mode into ${MODES_YAML_PATH}`);
+}
+
+// ---------------------------------------------------------------------------
+// Main
+// ---------------------------------------------------------------------------
+
+const projectPath = process.argv[2] ?? process.cwd();
+
+console.log("sdlc-harness Bob config merge");
+console.log("==============================");
+console.log(`Project path   : ${projectPath}`);
+console.log(`Bob settings   : ${BOB_SETTINGS_DIR}`);
+console.log(`MCP config     : ${MCP_JSON_PATH}`);
+console.log(`Modes config   : ${MODES_YAML_PATH}`);
+console.log("");
+
+ensureDir(BOB_DIR);
+ensureDir(BOB_SETTINGS_DIR);
+mergeMcpJson(projectPath);
+mergeModes(projectPath);
+
+console.log("");
+console.log("Done. Restart Bob to pick up the new MCP server and mode.");

