36 | // ---------------------------------------------------------------------------
37 | // Dotenv file parser — avoids a runtime dependency on the dotenv binary
38 | // ---------------------------------------------------------------------------
39 | 
40 | /**
41 |  * Parse a .env file and return key/value pairs.
42 |  * Lines starting with # and blank lines are ignored.
43 |  * Values may be quoted with single or double quotes (quotes are stripped).
44 |  */
45 | function parseDotenvFile(filePath: string): Record<string, string> {
46 |   let raw: string;
47 |   try {
48 |     raw = readFileSync(filePath, "utf-8");
49 |   } catch {
50 |     // File is optional — return empty record if it doesn't exist
51 |     return {};
52 |   }
53 | 
54 |   const result: Record<string, string> = {};
55 |   for (const line of raw.split(/\r?\n/)) {
56 |     const trimmed = line.trim();
57 |     if (!trimmed || trimmed.startsWith("#")) continue;
58 | 
59 |     const eqIndex = trimmed.indexOf("=");
60 |     if (eqIndex === -1) continue;
61 | 
62 |     const key = trimmed.slice(0, eqIndex).trim();
63 |     let value = trimmed.slice(eqIndex + 1).trim();
64 | 
65 |     // Strip surrounding quotes
66 |     if (
67 |       (value.startsWith('"') && value.endsWith('"')) ||
68 |       (value.startsWith("'") && value.endsWith("'"))
69 |     ) {
70 |       value = value.slice(1, -1);
71 |     }
72 | 
73 |     result[key] = value;
74 |   }
75 |   return result;
76 | }
