82 | /**
83 |  * Load and validate configuration.
84 |  *
85 |  * 1. Determines the env-file path (SDLC_ENV_FILE env var → default ".env").
86 |  * 2. Reads the file and merges into process.env — existing vars win.
87 |  * 3. Validates required vars are present and returns a typed Config object.
88 |  *
89 |  * Throws if any required variable is missing.
90 |  * Never logs values — only variable names.
91 |  */
92 | export function loadConfig(): Config {
93 |   // Determine env-file location
94 |   const envFilePath = resolve(
95 |     process.env["SDLC_ENV_FILE"] ?? ".env"
96 |   );
97 | 
98 |   // Parse file (silently skipped if absent)
99 |   const fileVars = parseDotenvFile(envFilePath);
100 | 
101 |   // Merge into process.env WITHOUT overriding existing values
102 |   for (const [key, value] of Object.entries(fileVars)) {
103 |     if (process.env[key] === undefined) {
104 |       process.env[key] = value;
105 |     }
106 |   }
107 | 
108 |   // Validate required variables
109 |   const required = [
110 |     "GITLAB_HOST",
111 |     "GITLAB_PROJECT",
112 |     "GITLAB_TOKEN",
113 |   ] as const;
114 | 
115 |   const missing = required.filter((key) => !process.env[key]);
116 | 
117 |   if (missing.length > 0) {
118 |     throw new Error(
119 |       `Missing required environment variables: ${missing.join(", ")}\n` +
120 |       `Set them in your .env file or in the process environment.\n` +
121 |       `See .env.example for the expected variable names.`
122 |     );
123 |   }
124 | 
125 |   return {
126 |     gitlabHost: process.env["GITLAB_HOST"]!.replace(/\/$/, ""),
127 |     gitlabProject: process.env["GITLAB_PROJECT"]!,
128 |     gitlabToken: [REDACTED],
129 |     debug: process.env["SDLC_DEBUG"] === "true" || process.env["SDLC_DEBUG"] === "1",
130 |   };
131 | }
132 | 
133 | /**
134 |  * Emit a debug message to stderr.
135 |  * Only produces output when config.debug is true.
136 |  * NEVER call this with a token or credential value.
137 |  */
138 | export function debugLog(config: Config, message: string): void {
139 |   if (config.debug) {
140 |     process.stderr.write(`[sdlc-harness debug] ${message}\n`);
141 |   }
142 | }
