45 | const SDLC_MODE_YAML = `
46 | - slug: sdlc-harness
47 |   name: "🔧 SDLC Harness"
48 |   roleDefinition: |
49 |     You are an SDLC governance agent for the sdlc-harness project.
50 |     Your job is to monitor GitLab work items and propose quality improvements:
51 |     drafting missing acceptance criteria, flagging ambiguous descriptions,
52 |     suggesting dependency links, and recommending state transitions.
53 |     Always present proposals for human review — never apply changes without approval.
54 |   groups:
55 |     - read
56 |     - edit
57 |     - mcp
58 |   source: project
59 | `;
60 | 
61 | // ---------------------------------------------------------------------------
62 | // Helpers
63 | // ---------------------------------------------------------------------------
64 | 
65 | function ensureBobDir() {
66 |   if (!existsSync(BOB_DIR)) {
67 |     mkdirSync(BOB_DIR, { recursive: true });
68 |     console.log(`Created ~/.bob directory.`);
69 |   }
70 | }
71 | 
72 | // ---------------------------------------------------------------------------
73 | // mcp.json merge
74 | // ---------------------------------------------------------------------------
75 | 
76 | function mergeMcpJson(absoluteProjectPath) {
77 |   let existing = {};
78 |   if (existsSync(MCP_JSON_PATH)) {
79 |     try {
80 |       existing = JSON.parse(readFileSync(MCP_JSON_PATH, "utf-8"));
81 |     } catch {
82 |       console.warn(`Warning: could not parse existing ${MCP_JSON_PATH} — will merge carefully.`);
83 |     }
84 |   }
85 | 
86 |   const servers = existing.mcpServers ?? existing.servers ?? {};
87 | 
88 |   if (servers["sdlc-harness"]) {
89 |     console.log(`✓ sdlc-harness already present in mcp.json — skipping.`);
90 |     return;
91 |   }
92 | 
93 |   // Resolve paths
94 |   const entry = JSON.parse(JSON.stringify(SDLC_SERVER_ENTRY));
95 |   const indexPath = join(absoluteProjectPath, "mcp-server", "dist", "index.js");
96 |   const envPath = join(absoluteProjectPath, ".env");
97 | 
98 |   entry["sdlc-harness"].args[0] = indexPath;
99 |   entry["sdlc-harness"].env["SDLC_ENV_FILE"] = envPath;
100 | 
101 |   const merged = {
102 |     ...existing,
103 |     mcpServers: {
104 |       ...servers,
105 |       ...entry,
106 |     },
107 |   };
108 | 
109 |   writeFileSync(MCP_JSON_PATH, JSON.stringify(merged, null, 2) + "\n", "utf-8");
110 |   console.log(`✓ Merged sdlc-harness into ${MCP_JSON_PATH}`);
111 | }
112 | 
113 | // ---------------------------------------------------------------------------
114 | // custom_modes.yaml merge
115 | // ---------------------------------------------------------------------------
116 | 
117 | function mergeModes() {
118 |   let existing = "";
119 |   if (existsSync(MODES_YAML_PATH)) {
120 |     existing = readFileSync(MODES_YAML_PATH, "utf-8");
121 |   }
122 | 
123 |   if (existing.includes("slug: sdlc-harness")) {
124 |     console.log(`✓ sdlc-harness mode already present in custom_modes.yaml — skipping.`);
125 |     return;
126 |   }
127 | 
128 |   // Append the mode entry — YAML arrays can be concatenated safely
129 |   const updated = existing.trimEnd() + "\n" + SDLC_MODE_YAML;
130 |   writeFileSync(MODES_YAML_PATH, updated, "utf-8");
131 |   console.log(`✓ Merged sdlc-harness mode into ${MODES_YAML_PATH}`);
132 | }
133 | 
134 | // ---------------------------------------------------------------------------
135 | // Main
136 | // ---------------------------------------------------------------------------
137 | 
138 | const projectPath = process.argv[2] ?? process.cwd();
139 | 
140 | console.log("sdlc-harness Bob config merge");
141 | console.log("==============================");
142 | console.log(`Project path : ${projectPath}`);
143 | console.log(`Bob dir      : ${BOB_DIR}`);
144 | console.log("");
145 | 
146 | ensureBobDir();
147 | mergeMcpJson(projectPath);
148 | mergeModes();
149 | 
150 | console.log("");
151 | console.log("Done. Restart Bob to pick up the new MCP server and mode.");
