    if (/\/issues\/1\/notes/.test(url)) return { status: 200, body: [] };
    if (/\/issues\/1$/.test(url)) return { status: 200, body: MOCK_ISSUE };
    if (/\/issues(\?|$)/.test(url)) return { status: 200, body: [MOCK_ISSUE] };
