    if (url.includes("/issues") && init?.method === "POST") {
      return { status: 200, body: { ...MOCK_ISSUE, iid: 2, title: MOCK_ISSUE.title } };
    }
    if (url.includes("/issues")) return { status: 200, body: [MOCK_ISSUE] };
    return { status: 404, body: { message: "Not found" } };
