1 | /**
2 |  * index.ts — MCP server entry point for sdlc-harness.
3 |  *
4 |  * Startup sequence:
5 |  *  1. Load configuration from the env file (throws with a clear message if
6 |  *     required variables are missing).
7 |  *  2. Construct the GitLab client with the loaded config.
8 |  *  3. Build the shared ToolContext.
9 |  *  4. Create an McpServer, register every tool from the registry.
10 |  *  5. Connect via StdioServerTransport and stay running.
11 |  *
12 |  * Stderr is kept quiet unless SDLC_DEBUG=true so Bob's stdio transport
13 |  * is not polluted with log noise.
14 |  */
15 | 
16 | import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
17 | import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
18 | import { loadConfig, debugLog } from "./env.js";
19 | import { GitLabClient } from "./gitlab-client.js";
20 | import { TOOLS } from "./tools.js";
21 | import type { ToolContext } from "./types.js";
22 | 
23 | async function main(): Promise<void> {
24 |   // 1. Load + validate configuration
25 |   const config = loadConfig();
26 |   debugLog(config, "Configuration loaded successfully.");
27 | 
28 |   // 2. Construct GitLab client
29 |   const gitlab = new GitLabClient(
30 |     config.gitlabHost,
31 |     config.gitlabToken,
32 |     config.gitlabProject
33 |   );
34 |   debugLog(config, `GitLab client ready for project: ${config.gitlabProject}`);
35 | 
36 |   // 3. Build shared context
37 |   const context: ToolContext = { gitlab, config };
38 | 
39 |   // 4. Create MCP server and register tools
40 |   const server = new McpServer({
41 |     name: "sdlc-harness",
42 |     version: "0.1.0",
43 |   });
44 | 
45 |   for (const tool of TOOLS) {
46 |     server.tool(
47 |       tool.name,
48 |       tool.description,
49 |       tool.argsSchema.shape ?? {},
50 |       async (args: unknown) => {
51 |         const parsed = tool.argsSchema.parse(args);
52 |         const result = await tool.execute(parsed, context);
53 |         return {
54 |           content: [
55 |             {
56 |               type: "text" as const,
57 |               text: JSON.stringify(result, null, 2),
58 |             },
59 |           ],
60 |         };
61 |       }
62 |     );
63 |     debugLog(config, `Registered tool: ${tool.name}`);
64 |   }
65 | 
66 |   debugLog(config, `${TOOLS.length} tool(s) registered. Connecting transport...`);
67 | 
68 |   // 5. Connect stdio transport and keep the process alive
69 |   const transport = new StdioServerTransport();
70 |   await server.connect(transport);
71 | 
72 |   // Reaching here means the transport has been connected.
73 |   // The process stays alive because the transport holds stdin open.
74 |   debugLog(config, "MCP server connected and listening on stdio.");
75 | }
76 | 
77 | main().catch((error: unknown) => {
78 |   // Only write to stderr — never stdout (that's the MCP protocol channel)
79 |   const message = error instanceof Error ? error.message : String(error);
80 |   process.stderr.write(`[sdlc-harness] Fatal startup error: ${message}\n`);
81 |   process.exit(1);
82 | });
