1 | /**
2 |  * gitlab-client.ts — GitLab REST API client for sdlc-harness.
3 |  *
4 |  * Design goals:
5 |  *  - Thin wrapper: one method per API operation needed by the tools.
6 |  *  - Testable: the class is constructed with a host + token so tests can
7 |  *    substitute fixture responses by swapping the underlying fetch function.
8 |  *  - No retries or pagination helpers here — keep it simple for the MVP.
9 |  *    Pagination is handled per-call by passing `per_page` and `page` params.
10 |  *
11 |  * All methods throw a GitLabApiError on non-2xx responses so callers get
12 |  * structured error info (status, message) rather than raw fetch rejections.
13 |  */
14 | 
15 | import type {
16 |   GitLabIssue,
17 |   GitLabLabel,
18 |   GitLabMR,
19 |   GitLabNote,
20 |   CreateIssueParams,
21 |   UpdateIssueParams,
22 |   CreateMRParams,
23 |   UpdateMRParams,
24 | } from "./types.js";
25 | 
26 | // ---------------------------------------------------------------------------
27 | // Error type
28 | // ---------------------------------------------------------------------------
29 | 
30 | /** Thrown when the GitLab API returns a non-2xx status. */
31 | export class GitLabApiError extends Error {
32 |   constructor(
33 |     public readonly status: number,
34 |     public readonly endpoint: string,
35 |     message: string
36 |   ) {
37 |     super(`GitLab API error ${status} on ${endpoint}: ${message}`);
38 |     this.name = "GitLabApiError";
39 |   }
40 | }
41 | 
42 | // ---------------------------------------------------------------------------
43 | // Fetch abstraction — injectable for tests
44 | // ---------------------------------------------------------------------------
45 | 
46 | /** Minimal fetch interface so tests can supply a mock. */
47 | export type FetchFn = (url: string, init?: RequestInit) => Promise<Response>;
48 | 
49 | // ---------------------------------------------------------------------------
50 | // GitLabClient
51 | // ---------------------------------------------------------------------------
52 | 
53 | export class GitLabClient {
54 |   private readonly baseUrl: string;
55 |   private readonly headers: Record<string, string>;
56 |   private readonly fetch: FetchFn;
57 | 
58 |   /**
59 |    * @param host        GitLab host, e.g. "https://gitlab.example.com". No trailing slash.
60 |    * @param token       Personal Access Token with `api` scope.
61 |    * @param projectPath Project path or numeric ID, e.g. "mygroup/myproject".
62 |    * @param fetchFn     Optional fetch override — defaults to global fetch (Node ≥18).
63 |    */
64 |   constructor(
65 |     host: string,
66 |     token: string,
67 |     public readonly projectPath: string,
68 |     fetchFn?: FetchFn
69 |   ) {
70 |     this.baseUrl = `${host}/api/v4`;
71 |     this.headers = {
72 |       "PRIVATE-TOKEN": token,
73 |       "Content-Type": "application/json",
74 |     };
75 |     // Node 18+ ships with global fetch; tests can inject a mock
76 |     this.fetch = fetchFn ?? (globalThis.fetch as FetchFn);
77 |   }
78 | 
79 |   // -------------------------------------------------------------------------
80 |   // Internal helpers
81 |   // -------------------------------------------------------------------------
82 | 
83 |   /** URL-encode a project path (slashes → %2F) for use in API endpoints. */
84 |   private encodedProject(): string {
85 |     return encodeURIComponent(this.projectPath);
86 |   }
87 | 
88 |   /** Build a full API URL for a project-scoped path. */
89 |   private projectUrl(path: string): string {
90 |     return `${this.baseUrl}/projects/${this.encodedProject()}${path}`;
91 |   }
92 | 
93 |   /**
94 |    * Execute an API request and return the parsed JSON body.
95 |    * Throws GitLabApiError on non-2xx responses.
96 |    */
97 |   private async request<T>(
98 |     url: string,
99 |     options: RequestInit = {}
100 |   ): Promise<T> {
101 |     const response = await this.fetch(url, {
102 |       ...options,
103 |       headers: {
104 |         ...this.headers,
105 |         ...(options.headers as Record<string, string> | undefined),
106 |       },
107 |     });
108 | 
109 |     if (!response.ok) {
110 |       let message = response.statusText;
111 |       try {
112 |         const body = (await response.json()) as { message?: string; error?: string };
113 |         message = body.message ?? body.error ?? message;
114 |       } catch {
115 |         // Ignore JSON parse errors on error responses
116 |       }
117 |       throw new GitLabApiError(response.status, url, message);
118 |     }
119 | 
120 |     // 204 No Content has no body
121 |     if (response.status === 204) {
122 |       return undefined as unknown as T;
123 |     }
124 | 
125 |     return response.json() as Promise<T>;
126 |   }
127 | 
128 |   // -------------------------------------------------------------------------
129 |   // Labels
130 |   // -------------------------------------------------------------------------
131 | 
132 |   /**
133 |    * List all labels for the project.
134 |    * @param page     Page number (1-based).
135 |    * @param perPage  Results per page (max 100).
136 |    */
137 |   async listLabels(page = 1, perPage = 100): Promise<GitLabLabel[]> {
138 |     const url = this.projectUrl(`/labels?page=${page}&per_page=${perPage}`);
139 |     return this.request<GitLabLabel[]>(url);
140 |   }
141 | 
142 |   // -------------------------------------------------------------------------
143 |   // Issues
144 |   // -------------------------------------------------------------------------
145 | 
146 |   /**
147 |    * List issues for the project.
148 |    *
149 |    * @param params  Optional filters: state, labels, assignee_username, milestone.
150 |    */
151 |   async listIssues(
152 |     params: {
153 |       state?: "opened" | "closed" | "all";
154 |       labels?: string;
155 |       assignee_username?: string;
156 |       milestone?: string;
157 |       search?: string;
158 |       page?: number;
159 |       per_page?: number;
160 |     } = {}
161 |   ): Promise<GitLabIssue[]> {
162 |     const query = new URLSearchParams();
163 |     if (params.state) query.set("state", params.state);
164 |     if (params.labels) query.set("labels", params.labels);
165 |     if (params.assignee_username) query.set("assignee_username", params.assignee_username);
166 |     if (params.milestone) query.set("milestone", params.milestone);
167 |     if (params.search) query.set("search", params.search);
168 |     query.set("page", String(params.page ?? 1));
169 |     query.set("per_page", String(params.per_page ?? 50));
170 | 
171 |     const url = this.projectUrl(`/issues?${query.toString()}`);
172 |     return this.request<GitLabIssue[]>(url);
173 |   }
174 | 
175 |   /**
176 |    * Get a single issue by its project-scoped IID.
177 |    */
178 |   async getIssue(iid: number): Promise<GitLabIssue> {
179 |     const url = this.projectUrl(`/issues/${iid}`);
180 |     return this.request<GitLabIssue>(url);
181 |   }
182 | 
183 |   /**
184 |    * Create a new issue.
185 |    */
186 |   async createIssue(params: CreateIssueParams): Promise<GitLabIssue> {
187 |     const url = this.projectUrl("/issues");
188 |     return this.request<GitLabIssue>(url, {
189 |       method: "POST",
190 |       body: JSON.stringify(params),
191 |     });
192 |   }
193 | 
194 |   /**
195 |    * Update an existing issue.
196 |    */
197 |   async updateIssue(iid: number, params: UpdateIssueParams): Promise<GitLabIssue> {
198 |     const url = this.projectUrl(`/issues/${iid}`);
199 |     return this.request<GitLabIssue>(url, {
200 |       method: "PUT",
201 |       body: JSON.stringify(params),
202 |     });
203 |   }
204 | 
205 |   /**
206 |    * List notes (comments) on an issue.
207 |    */
208 |   async listIssueNotes(iid: number): Promise<GitLabNote[]> {
209 |     const url = this.projectUrl(`/issues/${iid}/notes?per_page=100&sort=asc`);
210 |     return this.request<GitLabNote[]>(url);
211 |   }
212 | 
213 |   /**
214 |    * Add a comment to an issue.
215 |    */
216 |   async createIssueNote(iid: number, body: string): Promise<GitLabNote> {
217 |     const url = this.projectUrl(`/issues/${iid}/notes`);
218 |     return this.request<GitLabNote>(url, {
219 |       method: "POST",
220 |       body: JSON.stringify({ body }),
221 |     });
222 |   }
223 | 
