229 |    * List merge requests.
230 |    */
231 |   async listMRs(
232 |     params: {
233 |       state?: "opened" | "closed" | "merged" | "all";
234 |       labels?: string;
235 |       source_branch?: string;
236 |       target_branch?: string;
237 |       page?: number;
238 |       per_page?: number;
239 |     } = {}
240 |   ): Promise<GitLabMR[]> {
