242 |     if (params.state) query.set("state", params.state);
243 |     if (params.labels) query.set("labels", params.labels);
244 |     if (params.source_branch) query.set("source_branch", params.source_branch);
245 |     if (params.target_branch) query.set("target_branch", params.target_branch);
246 |     query.set("page", String(params.page ?? 1));
247 |     query.set("per_page", String(params.per_page ?? 50));
248 | 
249 |     const url = this.projectUrl(`/merge_requests?${query.toString()}`);
250 |     return this.request<GitLabMR[]>(url);
251 |   }
252 | 
