262 |    * Create a new merge request.
263 |    */
264 |   async createMR(params: CreateMRParams): Promise<GitLabMR> {
265 |     const url = this.projectUrl("/merge_requests");
266 |     return this.request<GitLabMR>(url, {
267 |       method: "POST",
268 |       body: JSON.stringify(params),
269 |     });
270 |   }
271 | 
272 |   /**
273 |    * Update an existing merge request.
274 |    */
275 |   async updateMR(iid: number, params: UpdateMRParams): Promise<GitLabMR> {
276 |     const url = this.projectUrl(`/merge_requests/${iid}`);
277 |     return this.request<GitLabMR>(url, {
278 |       method: "PUT",
279 |       body: JSON.stringify(params),
280 |     });
281 |   }
282 | 
283 |   /**
284 |    * List notes (comments) on a merge request.
285 |    */
286 |   async listMRNotes(iid: number): Promise<GitLabNote[]> {
287 |     const url = this.projectUrl(`/merge_requests/${iid}/notes?per_page=100&sort=asc`);
288 |     return this.request<GitLabNote[]>(url);
289 |   }
290 | 
