/**
 * tools.ts — tool registry for the sdlc-harness MCP server.
 *
 * All tools are registered here. index.ts imports this registry and
 * hands each entry to the MCP SDK to mount as a callable tool.
 *
 * To add a new tool: create its module under src/tools/, export a
 * ToolDefinition from it, then add it to the TOOLS array below.
 */

import type { ToolDefinition } from "./types.js";
import { gitlabIssueReaderTool } from "./tools/gitlab-issue-reader.js";
import { gitlabIssueWriterTool } from "./tools/gitlab-issue-writer.js";
import { gitlabMrReaderWriterTool } from "./tools/gitlab-mr-reader-writer.js";
import { workItemFormatTool } from "./tools/work-item-format.js";

/**
 * The complete list of tools exposed by this MCP server.
 * Order here determines the order they appear in tool listings.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const TOOLS: ToolDefinition<any>[] = [
  gitlabIssueReaderTool,
  gitlabIssueWriterTool,
  gitlabMrReaderWriterTool,
  workItemFormatTool,
];

/**
 * index.ts — MCP server entry point for sdlc-harness.
 *
 * Startup sequence:
 *  1. Load configuration from the env file (throws with a clear message if
 *     required variables are missing).
 *  2. Construct the GitLab client with the loaded config.
 *  3. Build the shared ToolContext.
 *  4. Create an McpServer, register every tool from the registry.
 *  5. Connect via StdioServerTransport and stay running.
 *
 * Stderr is kept quiet unless SDLC_DEBUG=true so Bob's stdio transport
 * is not polluted with log noise.
 */

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { loadConfig, debugLog } from "./env.js";
import { GitLabClient } from "./gitlab-client.js";
import { TOOLS } from "./tools.js";
import type { ToolContext } from "./types.js";

async function main(): Promise<void> {
  // 1. Load + validate configuration
  const config = loadConfig();
  debugLog(config, "Configuration loaded successfully.");

  // 2. Construct GitLab client
  const gitlab = new GitLabClient(
    config.gitlabHost,
    config.gitlabToken,
    config.gitlabProject
  );
  debugLog(config, `GitLab client ready for project: ${config.gitlabProject}`);

  // 3. Build shared context
  const context: ToolContext = { gitlab, config };

  // 4. Create MCP server and register tools
  const server = new McpServer({
    name: "sdlc-harness",
    version: "0.1.0",
  });

  for (const tool of TOOLS) {
    server.tool(
      tool.name,
      tool.description,
      tool.argsSchema.shape ?? {},
      async (args: unknown) => {
        const parsed = tool.argsSchema.parse(args);
        const result = await tool.execute(parsed, context);
        return {
          content: [
            {
              type: "text" as const,
              text: JSON.stringify(result, null, 2),
            },
          ],
        };
      }
    );
    debugLog(config, `Registered tool: ${tool.name}`);
  }

  debugLog(config, `${TOOLS.length} tool(s) registered. Connecting transport...`);

  // 5. Connect stdio transport and keep the process alive
  const transport = new StdioServerTransport();
  await server.connect(transport);

  // Reaching here means the transport has been connected.
  // The process stays alive because the transport holds stdin open.
  debugLog(config, "MCP server connected and listening on stdio.");
}

main().catch((error: unknown) => {
  // Only write to stderr — never stdout (that's the MCP protocol channel)
  const message = error instanceof Error ? error.message : String(error);
  process.stderr.write(`[sdlc-harness] Fatal startup error: ${message}\n`);
  process.exit(1);
});

/**
 * gitlab-issue-reader.ts — read GitLab issues, labels, and state.
 *
 * Exposed operations (controlled via the "action" discriminator):
 *  - list-issues   : list issues with optional filters
 *  - get-issue     : fetch a single issue by IID
 *  - list-labels   : fetch all project labels
 *  - list-notes    : fetch comments/notes on an issue
 */

import { z } from "zod";
import type { ToolDefinition, ToolContext } from "../types.js";

const argsSchema = z.discriminatedUnion("action", [
  z.object({
    action: z.literal("list-issues"),
    state: z.enum(["opened", "closed", "all"]).optional().describe(
      "Filter by issue state. Defaults to 'opened'."
    ),
    labels: z.string().optional().describe(
      "Comma-separated label names to filter by."
    ),
    assignee: z.string().optional().describe(
      "Filter by assignee username."
    ),
    milestone: z.string().optional().describe(
      "Filter by milestone title."
    ),
    search: z.string().optional().describe(
      "Full-text search across title and description."
    ),
    page: z.number().int().min(1).optional().describe(
      "Page number (1-based). Defaults to 1."
    ),
    per_page: z.number().int().min(1).max(100).optional().describe(
      "Results per page. Defaults to 50, max 100."
    ),
  }),
  z.object({
    action: z.literal("get-issue"),
    iid: z.number().int().min(1).describe(
      "Project-scoped issue IID."
    ),
  }),
  z.object({
    action: z.literal("list-labels"),
  }),
  z.object({
    action: z.literal("list-notes"),
    iid: z.number().int().min(1).describe(
      "Project-scoped issue IID to list notes for."
    ),
  }),
]);

type Args = z.infer<typeof argsSchema>;

export const gitlabIssueReaderTool: ToolDefinition<typeof argsSchema> = {
  name: "gitlab-issue-reader",
  description:
    "Read GitLab issues, labels, and notes (comments) for the configured project. " +
    "Use action='list-issues' to search/filter issues, 'get-issue' to fetch a single " +
    "issue by IID, 'list-labels' to fetch all project labels, and 'list-notes' to " +
    "fetch comments on an issue.",
  argsSchema,

  async execute(args: Args, context: ToolContext): Promise<unknown> {
    const { gitlab } = context;

    switch (args.action) {
      case "list-issues":
        return gitlab.listIssues({
          state: args.state ?? "opened",
          labels: args.labels,
          assignee_username: args.assignee,
          milestone: args.milestone,
          search: args.search,
          page: args.page,
          per_page: args.per_page,
        });

      case "get-issue":
        return gitlab.getIssue(args.iid);

      case "list-labels":
        return gitlab.listLabels();

      case "list-notes":
        return gitlab.listIssueNotes(args.iid);
    }
  },
};

/**
 * gitlab-issue-writer.ts — create and update GitLab issues.
 *
 * Exposed operations (controlled via the "action" discriminator):
 *  - create-issue    : create a new issue, with duplicate detection
 *  - update-issue    : update fields on an existing issue
 *  - close-issue     : close an issue by IID
 *  - reopen-issue    : reopen a closed issue
 *  - add-note        : post a comment on an issue
 *
 * Duplicate detection (create-issue):
 *  Before creating, the tool searches for open issues with the same title
 *  (case-insensitive exact match). If a duplicate is found it is returned
 *  with a `duplicate` flag set to true and NO new issue is created. The
 *  caller must explicitly pass `force: true` to bypass this check.
 */

import { z } from "zod";
import type { ToolDefinition, ToolContext, GitLabIssue } from "../types.js";

const argsSchema = z.discriminatedUnion("action", [
  z.object({
    action: z.literal("create-issue"),
    title: z.string().min(1).describe("Issue title."),
    description: z.string().optional().describe("Issue description (Markdown)."),
    labels: z.array(z.string()).optional().describe("Label names to apply."),
    milestone: z.string().optional().describe("Milestone title to assign."),
    assignee: z.string().optional().describe("Assignee username."),
    force: z.boolean().optional().describe(
      "Set true to create even if a duplicate title is found. Default false."
    ),
  }),
  z.object({
    action: z.literal("update-issue"),
    iid: z.number().int().min(1).describe("Project-scoped issue IID to update."),
    title: z.string().optional().describe("New title."),
    description: z.string().optional().describe("New description (Markdown)."),
    labels: z.array(z.string()).optional().describe(
      "Replacement label list. Replaces ALL existing labels."
    ),
    add_labels: z.array(z.string()).optional().describe(
      "Labels to ADD without touching existing ones."
    ),
    remove_labels: z.array(z.string()).optional().describe(
      "Labels to REMOVE without touching others."
    ),
  }),
  z.object({
    action: z.literal("close-issue"),
    iid: z.number().int().min(1).describe("Project-scoped issue IID to close."),
  }),
  z.object({
    action: z.literal("reopen-issue"),
    iid: z.number().int().min(1).describe("Project-scoped issue IID to reopen."),
  }),
  z.object({
    action: z.literal("add-note"),
    iid: z.number().int().min(1).describe("Project-scoped issue IID to comment on."),
    body: z.string().min(1).describe("Comment body (Markdown)."),
  }),
]);

type Args = z.infer<typeof argsSchema>;

// ---------------------------------------------------------------------------
// Duplicate detection helper
// ---------------------------------------------------------------------------

interface DuplicateCheckResult {
  isDuplicate: boolean;
  existing?: GitLabIssue;
}

async function checkDuplicate(
  title: string,
  context: ToolContext
): Promise<DuplicateCheckResult> {
  const normalised = title.trim().toLowerCase();
  const candidates = await context.gitlab.listIssues({
    state: "opened",
    search: title,
    per_page: 20,
  });

  const match = candidates.find(
    (issue) => issue.title.trim().toLowerCase() === normalised
  );

  return match
    ? { isDuplicate: true, existing: match }
    : { isDuplicate: false };
}

// ---------------------------------------------------------------------------
// Label merge helper
// ---------------------------------------------------------------------------

async function resolveLabels(
  iid: number,
  opts: {
    labels?: string[];
    add_labels?: string[];
    remove_labels?: string[];
  },
  context: ToolContext
): Promise<string | undefined> {
  if (opts.labels !== undefined) {
    // Full replacement
    return opts.labels.join(",");
  }

  if (opts.add_labels?.length || opts.remove_labels?.length) {
    // Partial update — fetch current labels
    const issue = await context.gitlab.getIssue(iid);
    const current = new Set(issue.labels);
    for (const l of opts.add_labels ?? []) current.add(l);
    for (const l of opts.remove_labels ?? []) current.delete(l);
    return [...current].join(",");
  }

  return undefined;
}

// ---------------------------------------------------------------------------
// Tool definition
// ---------------------------------------------------------------------------

export const gitlabIssueWriterTool: ToolDefinition<typeof argsSchema> = {
  name: "gitlab-issue-writer",
  description:
    "Create and update GitLab issues for the configured project. " +
    "action='create-issue' creates a new issue with duplicate detection (pass force=true to bypass). " +
    "action='update-issue' patches title, description, or labels on an existing issue. " +
    "action='close-issue' / 'reopen-issue' change issue state. " +
    "action='add-note' posts a comment.",
  argsSchema,

  async execute(args: Args, context: ToolContext): Promise<unknown> {
    const { gitlab } = context;

    switch (args.action) {
      case "create-issue": {
        // Duplicate check unless forced
        if (!args.force) {
          const check = await checkDuplicate(args.title, context);
          if (check.isDuplicate) {
            return {
              duplicate: true,
              message: `An open issue with this title already exists (IID #${check.existing!.iid}). Pass force=true to create anyway.`,
              existing: check.existing,
            };
          }
        }

        return gitlab.createIssue({
          title: args.title,
          description: args.description,
          labels: args.labels ? args.labels.join(",") as unknown as string[] : undefined,
        });
      }

      case "update-issue": {
        const labelString = await resolveLabels(
          args.iid,
          {
            labels: args.labels,
            add_labels: args.add_labels,
            remove_labels: args.remove_labels,
          },
          context
        );

        return gitlab.updateIssue(args.iid, {
          title: args.title,
          description: args.description,
          labels: labelString,
        });
      }

      case "close-issue":
        return gitlab.updateIssue(args.iid, { state_event: "close" });

      case "reopen-issue":
        return gitlab.updateIssue(args.iid, { state_event: "reopen" });

      case "add-note":
        return gitlab.createIssueNote(args.iid, args.body);
    }
  },
};

/**
 * gitlab-mr-reader-writer.ts — read and update GitLab Merge Requests.
 *
 * Exposed operations (controlled via the "action" discriminator):
 *  - list-mrs   : list merge requests with optional filters
 *  - get-mr     : fetch a single MR by IID
 *  - create-mr  : open a new merge request
 *  - update-mr  : update title, description, labels, or assignee
 *  - close-mr   : close (abandon) an open MR
 *  - list-notes : list notes/comments on an MR
 *  - add-note   : post a comment on an MR
 *
 * The state-transition agent uses this tool to detect when an MR is merged
 * ("state" = "merged" on get-mr) and propose the next issue transition.
 */

import { z } from "zod";
import type { ToolDefinition, ToolContext } from "../types.js";

const argsSchema = z.discriminatedUnion("action", [
  z.object({
    action: z.literal("list-mrs"),
    state: z.enum(["opened", "closed", "merged", "all"]).optional().describe(
      "Filter by MR state. Defaults to 'opened'."
    ),
    source_branch: z.string().optional().describe(
      "Filter by source branch name."
    ),
    target_branch: z.string().optional().describe(
      "Filter by target branch name."
    ),
    labels: z.string().optional().describe(
      "Comma-separated label names to filter by."
    ),
    page: z.number().int().min(1).optional().describe("Page number (1-based)."),
    per_page: z.number().int().min(1).max(100).optional().describe(
      "Results per page. Defaults to 50."
    ),
  }),
  z.object({
    action: z.literal("get-mr"),
    iid: z.number().int().min(1).describe("Project-scoped MR IID."),
  }),
  z.object({
    action: z.literal("create-mr"),
    source_branch: z.string().min(1).describe("Source branch name."),
    target_branch: z.string().min(1).describe("Target branch name."),
    title: z.string().min(1).describe("MR title (Conventional Commits recommended)."),
    description: z.string().optional().describe("MR description (Markdown)."),
    labels: z.string().optional().describe("Comma-separated labels to apply."),
    remove_source_branch: z.boolean().optional().describe(
      "Delete source branch after merge. Defaults to true."
    ),
  }),
  z.object({
    action: z.literal("update-mr"),
    iid: z.number().int().min(1).describe("Project-scoped MR IID to update."),
    title: z.string().optional().describe("New title."),
    description: z.string().optional().describe("New description (Markdown)."),
    labels: z.string().optional().describe(
      "Replacement comma-separated label list."
    ),
  }),
  z.object({
    action: z.literal("close-mr"),
    iid: z.number().int().min(1).describe("Project-scoped MR IID to close."),
  }),
  z.object({
    action: z.literal("list-notes"),
    iid: z.number().int().min(1).describe("Project-scoped MR IID."),
  }),
  z.object({
    action: z.literal("add-note"),
    iid: z.number().int().min(1).describe("Project-scoped MR IID."),
    body: z.string().min(1).describe("Comment body (Markdown)."),
  }),
]);

type Args = z.infer<typeof argsSchema>;

export const gitlabMrReaderWriterTool: ToolDefinition<typeof argsSchema> = {
  name: "gitlab-mr-reader-writer",
  description:
    "Read and manage GitLab Merge Requests for the configured project. " +
    "action='list-mrs' lists MRs with optional state/branch/label filters. " +
    "action='get-mr' fetches a single MR by IID (check .state for 'merged' to trigger state transitions). " +
    "action='create-mr' opens a new MR. " +
    "action='update-mr' patches title, description, or labels. " +
    "action='close-mr' abandons an open MR. " +
    "action='list-notes' / 'add-note' read and write MR comments.",
  argsSchema,

  async execute(args: Args, context: ToolContext): Promise<unknown> {
    const { gitlab } = context;

    switch (args.action) {
      case "list-mrs":
        return gitlab.listMRs({
          state: args.state ?? "opened",
          source_branch: args.source_branch,
          target_branch: args.target_branch,
          labels: args.labels,
          page: args.page,
          per_page: args.per_page,
        });

      case "get-mr":
        return gitlab.getMR(args.iid);

      case "create-mr":
        return gitlab.createMR({
          source_branch: args.source_branch,
          target_branch: args.target_branch,
          title: args.title,
          description: args.description,
          labels: args.labels,
          remove_source_branch: args.remove_source_branch ?? true,
        });

      case "update-mr":
        return gitlab.updateMR(args.iid, {
          title: args.title,
          description: args.description,
          labels: args.labels,
        });

      case "close-mr":
        return gitlab.updateMR(args.iid, { state_event: "close" });

      case "list-notes":
        return gitlab.listMRNotes(args.iid);

      case "add-note":
        return gitlab.createMRNote(args.iid, args.body);
    }
  },
};

/**
 * work-item-format.ts — canonical work item formatting standard.
 *
 * This tool encodes the team's formatting rules so every agent defers to
 * the same source of truth when drafting or reviewing work items.
 *
 * Exposed operations:
 *  - get-standard  : return the full formatting standard (all types)
 *  - get-template  : return the template for a specific work item type
 *  - validate-item : validate a title/description against the standard
 *                    and return a list of violations with suggested fixes
 */

import { z } from "zod";
import type { ToolDefinition, ToolContext } from "../types.js";

// ---------------------------------------------------------------------------
// The formatting standard (embedded — no network, no file read)
// ---------------------------------------------------------------------------

const WORK_ITEM_TYPES = ["Epic", "Feature", "User Story", "Bug", "Task"] as const;
type WorkItemType = (typeof WORK_ITEM_TYPES)[number];

interface WorkItemTemplate {
  type: WorkItemType;
  titleRules: string[];
  descriptionStructure: string;
  acceptanceCriteriaFormat: string;
  example: {
    title: string;
    description: string;
  };
}

const TEMPLATES: Record<WorkItemType, WorkItemTemplate> = {
  Epic: {
    type: "Epic",
    titleRules: [
      "Noun-phrase format: describe the capability, not the action.",
      "Title case for all significant words.",
      "No verbs at the start (avoid 'Implement', 'Build', 'Create').",
      "Max 60 characters.",
    ],
    descriptionStructure:
      "## Hypothesis\n" +
      "One sentence on why this initiative matters.\n\n" +
      "## Goals\n" +
      "Bulleted list of measurable outcomes.\n\n" +
      "## Scope\n" +
      "What is included and explicitly excluded.\n\n" +
      "## Child Features\n" +
      "- [ ] Feature 1\n" +
      "- [ ] Feature 2",
    acceptanceCriteriaFormat: "Epics do not carry acceptance criteria — use Features.",
    example: {
      title: "Automated Work Item Quality Governance",
      description:
        "## Hypothesis\nTeams lose hours per sprint correcting malformed work items.\n\n" +
        "## Goals\n- Reduce missing-AC rate by 80%\n- Reduce vague descriptions flagged in review by 60%\n\n" +
        "## Scope\nIn: GitLab Issues, AC drafting, ambiguity detection.\nOut: CI/CD pipelines, code review.\n\n" +
        "## Child Features\n- [ ] Acceptance Criteria Agent\n- [ ] Ambiguity Detection Agent",
    },
  },

  Feature: {
    type: "Feature",
    titleRules: [
      "Verb-noun phrase: start with an action verb.",
      "Title case for all significant words.",
      "Examples: 'Draft Missing Acceptance Criteria', 'Flag Ambiguous Descriptions'.",
      "Max 60 characters.",
    ],
    descriptionStructure:
      "## Overview\n" +
      "One to three sentences on what this feature delivers and why.\n\n" +
      "## Scope\n" +
      "Bulleted list of what is included. Add an 'Out of scope' sub-list.\n\n" +
      "## Child Stories\n" +
      "- [ ] User Story 1\n" +
      "- [ ] User Story 2",
    acceptanceCriteriaFormat: "Features do not carry acceptance criteria — use User Stories.",
    example: {
      title: "Draft Missing Acceptance Criteria",
      description:
        "## Overview\nAutomatically detects issues without AC and proposes well-formed Given-When-Then criteria.\n\n" +
        "## Scope\n- Detect issues with empty or absent AC field\n- Draft AC from description context\n- Present draft for human approval\n\nOut of scope: auto-apply without human review.\n\n" +
        "## Child Stories\n- [ ] As a dev, I can see AC suggestions inline in Bob",
    },
  },

  "User Story": {
    type: "User Story",
    titleRules: [
      "Connextra format: 'As a <role>, I can <action> so that <benefit>'.",
      "Sentence case (only first word and proper nouns capitalised).",
      "Max 120 characters.",
    ],
    descriptionStructure:
      "**As a** <role>, **I can** <action> **so that** <benefit>.\n\n" +
      "## Acceptance Criteria\n" +
      "<Given-When-Then criteria here>",
    acceptanceCriteriaFormat:
      "Given-When-Then format, one scenario per criterion:\n\n" +
      "**Given** <precondition>\n" +
      "**When** <action>\n" +
      "**Then** <expected outcome>\n\n" +
      "Each criterion must be independently verifiable.",
    example: {
      title: "As a developer, I can see suggested AC drafted by the agent so that I spend less time writing boilerplate",
      description:
        "**As a** developer, **I can** see acceptance criteria suggestions drafted by the AC agent " +
        "**so that** I spend less time writing boilerplate and more time on implementation.\n\n" +
        "## Acceptance Criteria\n\n" +
        "**Given** an issue has no acceptance criteria\n" +
        "**When** the AC agent runs\n" +
        "**Then** a draft AC block appears as a comment on the issue\n\n" +
        "**Given** a draft AC is posted\n" +
        "**When** the developer reviews it in Bob\n" +
        "**Then** they can approve, edit, or reject the suggestion in natural language",
    },
  },

  Bug: {
    type: "Bug",
    titleRules: [
      "Format: '<Component>: <symptom observed>'.",
      "Sentence case.",
      "Describe the symptom, not the cause.",
      "Max 120 characters.",
    ],
    descriptionStructure:
      "## Steps to Reproduce\n" +
      "Numbered list of exact reproduction steps.\n\n" +
      "## Expected Behaviour\n" +
      "What should happen.\n\n" +
      "## Actual Behaviour\n" +
      "What actually happens.\n\n" +
      "## Environment\n" +
      "OS, browser, version, etc.",
    acceptanceCriteriaFormat:
      "Given-When-Then format focused on the fix:\n\n" +
      "**Given** <condition that previously triggered the bug>\n" +
      "**When** <action that triggered it>\n" +
      "**Then** <correct behaviour now expected>",
    example: {
      title: "AC Agent: draft is not posted when issue description is empty",
      description:
        "## Steps to Reproduce\n1. Create an issue with no description.\n2. Run the AC agent.\n\n" +
        "## Expected Behaviour\nThe agent posts a comment noting it cannot draft AC without a description.\n\n" +
        "## Actual Behaviour\nThe agent silently skips the issue with no feedback.\n\n" +
        "## Environment\nsdlc-harness v0.1, self-hosted GitLab CE 16.x",
    },
  },

  Task: {
    type: "Task",
    titleRules: [
      "Imperative verb phrase: start with a verb.",
      "Sentence case.",
      "Examples: 'Add rate-limit handling to gitlab-client', 'Write smoke test for issue reader'.",
      "Max 80 characters.",
    ],
    descriptionStructure:
      "One to three sentences describing the technical work to be done.\n" +
      "Include any relevant file paths, interfaces, or constraints.",
    acceptanceCriteriaFormat: "Tasks do not require formal AC — use a clear Definition of Done in the description.",
    example: {
      title: "Add pagination support to listIssues in gitlab-client",
      description:
        "Extend `GitLabClient.listIssues()` to accept `page` and `per_page` parameters " +
        "and pass them through to the GitLab API. Update the corresponding tool schema. " +
        "Verified when `npm run smoke` passes with paginated fixture data.",
    },
  },
};

// ---------------------------------------------------------------------------
// Validation helper
// ---------------------------------------------------------------------------

interface ValidationViolation {
  field: "title" | "description" | "acceptanceCriteria";
  rule: string;
  suggestion?: string;
}

function validateItem(
  type: WorkItemType,
  title: string,
  description?: string,
  acceptanceCriteria?: string
): ValidationViolation[] {
  const template = TEMPLATES[type];
  const violations: ValidationViolation[] = [];

  // --- Title checks ---
  if (title.length > 120) {
    violations.push({
      field: "title",
      rule: "Title exceeds 120 characters.",
      suggestion: "Shorten to the core action/outcome.",
    });
  }
  if (type === "User Story" && !title.toLowerCase().startsWith("as a")) {
    violations.push({
      field: "title",
      rule: "User Story titles must follow Connextra format: 'As a <role>, I can...'.",
      suggestion: `Rewrite as: "${template.example.title}"`,
    });
  }
  if (type === "Bug" && !title.includes(":")) {
    violations.push({
      field: "title",
      rule: "Bug titles must follow '<Component>: <symptom>' format.",
      suggestion: `Example: "${template.example.title}"`,
    });
  }

  // --- Description checks ---
  if (!description || description.trim().length === 0) {
    violations.push({
      field: "description",
      rule: "Description is empty.",
      suggestion: `Use the ${type} template:\n${template.descriptionStructure}`,
    });
  }

  // --- Acceptance criteria checks (User Story and Bug only) ---
  if (type === "User Story" || type === "Bug") {
    if (!acceptanceCriteria || acceptanceCriteria.trim().length === 0) {
      violations.push({
        field: "acceptanceCriteria",
        rule: "Acceptance criteria are required for User Stories and Bugs.",
        suggestion: `Use Given-When-Then format:\n${template.acceptanceCriteriaFormat}`,
      });
    } else {
      const hasGiven = /given/i.test(acceptanceCriteria);
      const hasWhen = /when/i.test(acceptanceCriteria);
      const hasThen = /then/i.test(acceptanceCriteria);
      if (!hasGiven || !hasWhen || !hasThen) {
        violations.push({
          field: "acceptanceCriteria",
          rule: "Acceptance criteria must use Given-When-Then structure.",
          suggestion: `Example:\n${template.acceptanceCriteriaFormat}`,
        });
      }
    }
  }

  return violations;
}

// ---------------------------------------------------------------------------
// Tool schema
// ---------------------------------------------------------------------------

const argsSchema = z.discriminatedUnion("action", [
  z.object({
    action: z.literal("get-standard"),
    type: z.enum(WORK_ITEM_TYPES).optional().describe(
      "Return standard for a specific type only. Omit for the full standard."
    ),
  }),
  z.object({
    action: z.literal("get-template"),
    type: z.enum(WORK_ITEM_TYPES).describe("Work item type to get the template for."),
  }),
  z.object({
    action: z.literal("validate-item"),
    type: z.enum(WORK_ITEM_TYPES).describe("Work item type to validate against."),
    title: z.string().describe("Issue title to validate."),
    description: z.string().optional().describe("Issue description to validate."),
    acceptanceCriteria: z.string().optional().describe(
      "Acceptance criteria to validate (relevant for User Story and Bug)."
    ),
  }),
]);

type Args = z.infer<typeof argsSchema>;

// ---------------------------------------------------------------------------
// Tool definition
// ---------------------------------------------------------------------------

export const workItemFormatTool: ToolDefinition<typeof argsSchema> = {
  name: "work-item-format",
  description:
    "Return and validate work item formatting standards. " +
    "action='get-standard' returns the full formatting standard (optionally filtered to one type). " +
    "action='get-template' returns the template (structure + example) for a specific type. " +
    "action='validate-item' checks a title/description/AC against the standard and returns violations with fixes.",
  argsSchema,

  // Context is not needed (all data is embedded) but must match the signature
  async execute(args: Args, _context: ToolContext): Promise<unknown> {
    switch (args.action) {
      case "get-standard": {
        if (args.type) {
          return { standard: TEMPLATES[args.type] };
        }
        return { standard: TEMPLATES };
      }

      case "get-template": {
        return { template: TEMPLATES[args.type] };
      }

      case "validate-item": {
        const violations = validateItem(
          args.type,
          args.title,
          args.description,
          args.acceptanceCriteria
        );
        return {
          valid: violations.length === 0,
          violations,
          template: TEMPLATES[args.type],
        };
      }
    }
  },
};

/**
 * tools.ts — tool registry for the sdlc-harness MCP server.
 *
 * All tools are registered here. index.ts imports this registry and
 * hands each entry to the MCP SDK to mount as a callable tool.
 *
 * To add a new tool: create its module under src/tools/, export a
 * ToolDefinition from it, then add it to the TOOLS array below.
 */

import type { ToolDefinition } from "./types.js";
import { gitlabIssueReaderTool } from "./tools/gitlab-issue-reader.js";
import { gitlabIssueWriterTool } from "./tools/gitlab-issue-writer.js";
import { gitlabMrReaderWriterTool } from "./tools/gitlab-mr-reader-writer.js";
import { workItemFormatTool } from "./tools/work-item-format.js";

/**
 * The complete list of tools exposed by this MCP server.
 * Order here determines the order they appear in tool listings.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const TOOLS: ToolDefinition<any>[] = [
  gitlabIssueReaderTool,
  gitlabIssueWriterTool,
  gitlabMrReaderWriterTool,
  workItemFormatTool,
];

